CREATE OR REPLACE FUNCTION mission_factory_owner.c384_human_bind_seal_v1(p_session uuid, p_lineage uuid, p_version bigint, p_episode uuid, p_definition uuid, p_request uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v mission_factory_owner.c384_authoring_versions;b mission_factory_owner.c384_human_bindings;
m public.master_v2_sessions;e mission_factory_owner.quest_episodes;d mission_generic_owner.definitions;
q mission_factory_owner.quest_run_sources;l public.locations;doc_episode jsonb;identity jsonb;users uuid[];n integer;u uuid:=auth.uid();
BEGIN
IF u IS NULL OR auth.role() IS DISTINCT FROM 'authenticated' OR p_session IS NULL OR p_lineage IS NULL OR p_version IS NULL
OR p_episode IS NULL OR p_definition IS NULL OR p_request IS NULL OR p_version<=0
THEN RAISE EXCEPTION 'C384_NORMAL_AUTH_BIND_INPUT_REQUIRED' USING ERRCODE='42501';END IF;
PERFORM mission_factory_owner.assert_editor(u);
PERFORM pg_advisory_xact_lock(hashtextextended('c384-bind:'||p_session::text,384));
SELECT * INTO b FROM mission_factory_owner.c384_human_bindings WHERE session_id=p_session;
IF FOUND THEN
PERFORM mission_factory_owner.c384_human_identity_v1(p_session);
IF b.lineage_id IS DISTINCT FROM p_lineage OR b.authoring_version IS DISTINCT FROM p_version OR b.episode_id IS DISTINCT FROM p_episode
OR b.definition_id IS DISTINCT FROM p_definition OR b.bind_request IS DISTINCT FROM p_request
THEN RAISE EXCEPTION 'C384_BIND_REQUEST_CONFLICT' USING ERRCODE='22023';END IF;RETURN b.binding_snapshot;
END IF;
IF NOT EXISTS(SELECT 1 FROM mission_factory_owner.c384_control WHERE singleton AND enabled)
THEN RAISE EXCEPTION 'C384_INTEGRATION_DISABLED' USING ERRCODE='42501';END IF;
SELECT * INTO STRICT v FROM mission_factory_owner.c384_authoring_versions WHERE lineage_id=p_lineage AND version=p_version FOR SHARE;
SELECT * INTO STRICT m FROM public.master_v2_sessions WHERE id=p_session FOR UPDATE;
SELECT * INTO STRICT e FROM mission_factory_owner.quest_episodes WHERE id=p_episode FOR SHARE;
SELECT * INTO STRICT d FROM mission_generic_owner.definitions WHERE id=p_definition FOR SHARE;
SELECT * INTO STRICT q FROM mission_factory_owner.quest_run_sources WHERE session_id=p_session FOR SHARE;
SELECT * INTO STRICT l FROM public.locations WHERE id=m.location_id FOR SHARE;
SELECT value INTO STRICT doc_episode FROM jsonb_array_elements(v.document#>'{quest,episodes}') x WHERE value->>'episode_key'=e.episode_key;
PERFORM mission_factory_owner.c384_validate_dual_draft_v3(v.document);
SELECT count(*),array_agg(p.user_id_snapshot ORDER BY p.character_id) INTO n,users
FROM public.master_v2_participants p JOIN public.characters c ON c.id=p.character_id AND c.user_id=p.user_id_snapshot
WHERE p.session_id=p_session AND p.left_at IS NULL AND p.engagement_state='attivo';
IF v.author_user IS DISTINCT FROM u OR m.master_user IS DISTINCT FROM u OR m.owner_kind IS DISTINCT FROM 'human'
OR public.master_v2_is_master(u) IS DISTINCT FROM true OR m.tipo IS DISTINCT FROM 'quest' OR m.mission_id IS NOT NULL
OR m.stato IS DISTINCT FROM 'preparazione' OR m.closed_at IS NOT NULL OR m.suspended_at IS NOT NULL
OR q.state IS DISTINCT FROM 'prepared' OR q.episode_id IS DISTINCT FROM e.id OR q.definition_id IS DISTINCT FROM d.id
OR q.source_sha256 IS DISTINCT FROM e.source_sha256 OR q.definition_sha256 IS DISTINCT FROM d.definition_sha256
OR q.location_id IS DISTINCT FROM m.location_id OR q.roster_character_ids IS DISTINCT FROM e.member_character_ids
OR q.roster_snapshot_sha256 IS DISTINCT FROM mission_factory_owner.sha(to_jsonb(q.roster_character_ids))
OR n NOT BETWEEN 1 AND 4 OR n<>cardinality(q.roster_character_ids)
OR EXISTS(SELECT 1 FROM unnest(q.roster_character_ids) x(id) WHERE NOT EXISTS(SELECT 1 FROM public.master_v2_participants p
WHERE p.session_id=p_session AND p.character_id=x.id AND p.left_at IS NULL AND p.engagement_state='attivo'))
OR ((l.id IS DISTINCT FROM '0b85f354-9cdb-47e1-baf9-3d266bb7e06b'::uuid OR NOT l.is_active OR l.is_test IS DISTINCT FROM true
OR q.availability_scope IS DISTINCT FROM 'staff' OR q.execution_context IS DISTINCT FROM 'staff_simulation'
OR combat_consumer_private.staff_test_allowed(l.id,array_append(users,u),false) IS DISTINCT FROM true) AND NOT (EXISTS(SELECT 1 FROM mission_factory_owner.quest_arcs gx_a
JOIN mission_factory_owner.quest_episodes gx_e ON gx_e.arc_id=gx_a.id AND gx_e.id=q.episode_id
JOIN public.locations gx_l ON gx_l.id=q.location_id
WHERE gx_a.id=q.arc_id AND q.availability_scope='public' AND gx_a.availability_scope='public'
AND gx_a.source_document->>'content_kind'='quest_human'
AND q.execution_context=gx_a.execution_context AND q.execution_context IN('staff_simulation','public_real')
AND q.public_release_sha256 IS NOT DISTINCT FROM gx_a.public_release_sha256
AND q.execution_qualification_sha256 IS NOT DISTINCT FROM gx_a.execution_qualification_sha256
AND q.source_sha256=gx_e.source_sha256 AND gx_e.source_sha256=mission_factory_owner.sha(gx_e.source_document)
AND q.roster_character_ids IS NOT DISTINCT FROM gx_e.member_character_ids
AND gx_l.is_active AND gx_l.is_test=(q.execution_context='staff_simulation')
AND ((q.execution_context='staff_simulation' AND gx_l.id='0b85f354-9cdb-47e1-baf9-3d266bb7e06b'::uuid
AND combat_consumer_private.staff_test_allowed(gx_l.id,array_append(ARRAY(SELECT gx_c.user_id FROM unnest(q.roster_character_ids)WITH ORDINALITY gx_ids(id,ord) JOIN public.characters gx_c ON gx_c.id=gx_ids.id ORDER BY gx_ids.ord),auth.uid()),false) IS TRUE)
OR(q.execution_context='public_real' AND NOT coalesce(gx_l.is_exam_room,false)))
AND mission_factory_owner.human_ordinary_arc_scope_v1(gx_a.id,true) IS TRUE)))
OR v.document#>>'{variants,human,state}' IS DISTINCT FROM 'complete'
OR doc_episode IS DISTINCT FROM e.source_document OR e.source_sha256 IS DISTINCT FROM mission_factory_owner.sha(e.source_document)
OR d.definition_sha256 IS DISTINCT FROM mission_internal.fingerprint(d.definition)
OR d.definition->>'quest_episode_id' IS DISTINCT FROM e.id::text OR d.definition->>'source_sha256' IS DISTINCT FROM e.source_sha256
OR NOT EXISTS(SELECT 1 FROM mission_generic_owner.run_bindings rb WHERE rb.master_session_id=p_session
AND rb.definition_id=d.id AND rb.snapshot_sha256=mission_internal.fingerprint(rb.snapshot))
THEN RAISE EXCEPTION 'C384_COHERENT_PROTECTED_HUMAN_SOURCE_REQUIRED' USING ERRCODE='42501';END IF;
identity:=jsonb_build_object('schema_version','quest-human-binding/3','direction_mode','human','session_id',p_session,
'assigned_master',u,'lineage_id',p_lineage,'authoring_version',p_version,'authoring_sha256',v.document_sha256,
'episode_id',e.id,'source_sha256',e.source_sha256,'definition_sha256',d.definition_sha256,
'human_variant_sha256',v.human_variant_sha256,'mechanical_sha256',v.mechanical_sha256);
INSERT INTO mission_factory_owner.c384_human_bindings(session_id,lineage_id,authoring_version,assigned_master,episode_id,definition_id,
source_sha256,definition_sha256,binding_snapshot,binding_sha256,bind_request)
VALUES(p_session,p_lineage,p_version,u,e.id,d.id,e.source_sha256,d.definition_sha256,identity,mission_factory_owner.sha(identity),p_request);
PERFORM mission_factory_owner.c384_human_identity_v1(p_session);
RETURN identity;
END $function$

CREATE OR REPLACE FUNCTION mission_factory_owner.c395_active_human_assert_v1(p_session uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE m public.master_v2_sessions;q mission_factory_owner.quest_run_sources;users uuid[];
BEGIN
PERFORM mission_factory_owner.c395_source_assert_v1(p_session);
SELECT * INTO STRICT m FROM public.master_v2_sessions WHERE id=p_session FOR SHARE;
SELECT * INTO STRICT q FROM mission_factory_owner.quest_run_sources WHERE session_id=p_session FOR SHARE;
SELECT array_agg(c.user_id ORDER BY c.id) INTO users FROM unnest(q.roster_character_ids) x(id) JOIN public.characters c ON c.id=x.id;
IF q.state IS DISTINCT FROM 'started' OR m.closed_at IS NOT NULL OR m.suspended_at IS NOT NULL OR m.stato NOT IN('in_corso','chiusura')
OR m.master_user IS DISTINCT FROM auth.uid() OR auth.role() IS DISTINCT FROM 'authenticated'
OR ((q.location_id IS DISTINCT FROM '0b85f354-9cdb-47e1-baf9-3d266bb7e06b'::uuid
 OR q.availability_scope IS DISTINCT FROM 'staff' OR q.execution_context IS DISTINCT FROM 'staff_simulation'
 OR combat_consumer_private.staff_test_allowed(q.location_id,array_append(users,auth.uid()),false) IS DISTINCT FROM true)
 AND mission_factory_owner.human_ordinary_source_v1(p_session,true) IS NULL)
THEN RAISE EXCEPTION 'C395_HUMAN_ACTIVE_STAFF_SCOPE_REQUIRED' USING ERRCODE='42501';END IF;
END $function$

CREATE OR REPLACE FUNCTION mission_factory_owner.c395_prepare_assert_v1(p_lineage uuid, p_version bigint, p_episode uuid, p_location uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v mission_factory_owner.c384_authoring_versions;u uuid:=auth.uid();
a mission_factory_owner.quest_arcs;e mission_factory_owner.quest_episodes;ordinary boolean:=false;
BEGIN
SELECT * INTO e FROM mission_factory_owner.quest_episodes WHERE id=p_episode;
SELECT * INTO a FROM mission_factory_owner.quest_arcs WHERE id=e.arc_id;
ordinary:=a.availability_scope='public' AND a.execution_context='public_real'
 AND mission_public_owner.human_positive_qualification_v1(a.public_release_sha256,true) IS NOT NULL
 AND EXISTS(SELECT 1 FROM public.locations l WHERE l.id=p_location AND l.is_active AND NOT l.is_test AND NOT coalesce(l.is_exam_room,false));
IF u IS NULL OR auth.role() IS DISTINCT FROM 'authenticated' OR p_lineage IS NULL OR p_version IS NULL OR p_episode IS NULL
OR (CASE WHEN a.availability_scope='public' AND a.execution_context='public_real' THEN ordinary IS DISTINCT FROM true ELSE p_location IS DISTINCT FROM '0b85f354-9cdb-47e1-baf9-3d266bb7e06b'::uuid END)
THEN RAISE EXCEPTION 'C395_NORMAL_STAFF_HUMAN_INPUT_REQUIRED' USING ERRCODE='42501';END IF;
PERFORM mission_factory_owner.assert_editor(u);
IF public.master_v2_is_master(u) IS DISTINCT FROM true
OR NOT EXISTS(SELECT 1 FROM mission_factory_owner.c395_control WHERE singleton AND prepare_enabled)
OR NOT EXISTS(SELECT 1 FROM mission_factory_owner.c384_control WHERE singleton AND enabled)
THEN RAISE EXCEPTION 'C395_HUMAN_PREPARE_DISABLED' USING ERRCODE='42501';END IF;
SELECT * INTO STRICT v FROM mission_factory_owner.c384_authoring_versions WHERE lineage_id=p_lineage AND version=p_version FOR SHARE;
IF v.author_user IS DISTINCT FROM u OR v.document#>>'{variants,human,state}' IS DISTINCT FROM 'complete'
THEN RAISE EXCEPTION 'C395_HUMAN_VERSION_AUTHORITY_REQUIRED' USING ERRCODE='42501';END IF;
PERFORM mission_factory_owner.c384_validate_dual_draft_v3(v.document);
PERFORM mission_factory_owner.quest_operator_assert_v3(p_episode);
END $function$

CREATE OR REPLACE FUNCTION mission_factory_owner.c395_revision_issue_v1(p_lineage uuid, p_version bigint, p_arc uuid, p_episode uuid, p_request uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v mission_factory_owner.c384_authoring_versions;e mission_factory_owner.quest_episodes;a mission_factory_owner.quest_arcs;
h mission_factory_owner.c395_quest_revisions;ep jsonb;arenas jsonb;rid uuid;u uuid:=auth.uid();
BEGIN
IF u IS NULL OR auth.role() IS DISTINCT FROM 'authenticated' OR p_request IS NULL
THEN RAISE EXCEPTION 'C395_NORMAL_AUTH_REVISION_REQUIRED' USING ERRCODE='42501';END IF;
PERFORM mission_factory_owner.assert_editor(u);
-- A scoped renewal authorizes only the existing prepared scene and its original prepare replay.
IF EXISTS(SELECT 1 FROM mission_public_owner.public_qualification_attestations_v1 lease_prepare_scope JOIN mission_factory_owner.quest_fixed30_admission lease_prepare_g ON lease_prepare_g.singleton AND lease_prepare_g.public_staff_enabled WHERE lease_prepare_scope.created_by='postgres'::name AND lease_prepare_scope.payload_sha256=mission_factory_owner.sha(lease_prepare_scope.payload) AND lease_prepare_scope.payload->>'schema_version'='human-custom-staff-lease-renewal/1' AND lease_prepare_scope.payload->>'arc_id'=p_arc::text AND lease_prepare_scope.payload->>'draft_id'=lease_prepare_g.public_staff_draft_id::text)
AND NOT EXISTS(SELECT 1 FROM mission_factory_owner.quest_run_sources lease_prepare_q JOIN mission_public_owner.public_qualification_attestations_v1 lease_prepare_proof ON lease_prepare_proof.payload->>'session_id'=lease_prepare_q.session_id::text AND lease_prepare_proof.payload->>'schema_version'='human-custom-staff-lease-renewal/1' AND lease_prepare_proof.created_by='postgres'::name AND lease_prepare_proof.payload_sha256=mission_factory_owner.sha(lease_prepare_proof.payload) WHERE lease_prepare_q.arc_id=p_arc AND lease_prepare_q.episode_id=p_episode AND lease_prepare_q.prepare_request_key=p_request AND lease_prepare_proof.payload->>'arc_id'=p_arc::text AND lease_prepare_proof.payload->>'assigned_master'=u::text)
THEN RAISE EXCEPTION 'HUMAN_STAFF_RENEWAL_PREPARE_REPLAY_ONLY' USING ERRCODE='42501';END IF;

PERFORM pg_advisory_xact_lock(hashtextextended('c395-revision:'||p_episode::text,395));
SELECT * INTO h FROM mission_factory_owner.c395_quest_revisions WHERE episode_id=p_episode;
IF FOUND THEN
IF (h.lineage_id,h.authoring_version,h.arc_id,h.assigned_master,h.request_key) IS DISTINCT FROM (p_lineage,p_version,p_arc,u,p_request)
THEN RAISE EXCEPTION 'C395_REVISION_REQUEST_CONFLICT' USING ERRCODE='22023';END IF;RETURN h.id;
END IF;
SELECT * INTO STRICT v FROM mission_factory_owner.c384_authoring_versions WHERE lineage_id=p_lineage AND version=p_version FOR SHARE;
SELECT * INTO STRICT e FROM mission_factory_owner.quest_episodes WHERE id=p_episode AND arc_id=p_arc FOR SHARE;
SELECT * INTO STRICT a FROM mission_factory_owner.quest_arcs WHERE id=p_arc FOR SHARE;
SELECT value INTO STRICT ep FROM jsonb_array_elements(v.document#>'{quest,episodes}') x WHERE value->>'episode_key'=e.episode_key;
IF v.author_user IS DISTINCT FROM u OR a.created_by IS DISTINCT FROM u OR v.document#>>'{variants,human,state}' IS DISTINCT FROM 'complete'
OR ep IS DISTINCT FROM e.source_document OR e.source_sha256 IS DISTINCT FROM mission_factory_owner.sha(ep)
OR ((a.availability_scope IS DISTINCT FROM 'staff' OR a.execution_context IS DISTINCT FROM 'staff_simulation') AND NOT(a.availability_scope='public' AND a.source_document->>'content_kind'='quest_human' AND mission_factory_owner.human_ordinary_arc_scope_v1(a.id,true)))
OR e.state IS DISTINCT FROM 'source_only' OR v.document#>>'{quest,quest_kind}' IS DISTINCT FROM a.quest_kind
OR NOT EXISTS(SELECT 1 FROM mission_factory_owner.c395_control WHERE singleton AND prepare_enabled)
THEN RAISE EXCEPTION 'C395_IMMUTABLE_COMMON_SOURCE_REQUIRED' USING ERRCODE='42501';END IF;
PERFORM mission_factory_owner.c384_validate_dual_draft_v3(v.document);
IF mission_factory_owner.quest_compile_check_v1(e.id) IS DISTINCT FROM '[]'::jsonb
THEN RAISE EXCEPTION 'C395_NATIVE_COMPILE_QUALIFICATION_REQUIRED' USING ERRCODE='42501';END IF;
-- Arena refs are authored/versioned; no UUID or qualification is invented.
SELECT coalesce(jsonb_agg(jsonb_build_object('step_key',x.value->>'step_key',
'template_key',x.value#>>'{arena_ref,template_key}','template_version',x.value#>'{arena_ref,template_version}',
'zone_key',x.value#>>'{arena_ref,zone_key}',
'catalog_sha256',combat_panel_private.universal_arena_hash(x.value#>>'{arena_ref,template_key}',(x.value#>>'{arena_ref,template_version}')::integer)) ORDER BY x.value->>'step_key'),'[]'::jsonb)
INTO arenas FROM jsonb_array_elements(ep->'maps') x WHERE jsonb_typeof(x.value->'arena_ref')='object';
rid:=extensions.uuid_generate_v5(p_request,'mission-factory:human-quest-revision/1');
INSERT INTO mission_factory_owner.c395_quest_revisions(id,lineage_id,authoring_version,arc_id,episode_id,assigned_master,source_sha256,document,document_sha256,arena_sources,request_key)
VALUES(rid,p_lineage,p_version,p_arc,p_episode,u,e.source_sha256,v.document#>'{variants,human,document}',
mission_factory_owner.sha(v.document#>'{variants,human,document}'),arenas,p_request);
RETURN rid;
END $function$

CREATE OR REPLACE FUNCTION mission_factory_owner.c407_identity_v1(p_session uuid)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE q mission_factory_owner.quest_run_sources;m public.master_v2_sessions;users uuid[];
BEGIN
PERFORM mission_factory_owner.c384_human_identity_v1(p_session);
PERFORM mission_factory_owner.c395_revision_assert_v1(p_session);
SELECT * INTO STRICT q FROM mission_factory_owner.quest_run_sources WHERE session_id=p_session;
SELECT * INTO STRICT m FROM public.master_v2_sessions WHERE id=p_session;
SELECT array_agg(c.user_id ORDER BY c.id) INTO users FROM unnest(q.roster_character_ids)x(id) JOIN public.characters c ON c.id=x.id;
IF auth.uid() IS NULL OR auth.role() IS DISTINCT FROM 'authenticated' OR m.master_user IS DISTINCT FROM auth.uid()
OR public.master_v2_is_master(auth.uid()) IS DISTINCT FROM true OR m.owner_kind IS DISTINCT FROM 'human' OR m.mission_id IS NOT NULL OR m.tipo IS DISTINCT FROM 'quest'
OR m.location_id IS DISTINCT FROM q.location_id
OR cardinality(q.roster_character_ids) NOT BETWEEN 1 AND 4 OR cardinality(users) IS DISTINCT FROM cardinality(q.roster_character_ids)
OR ((q.location_id IS DISTINCT FROM '0b85f354-9cdb-47e1-baf9-3d266bb7e06b'::uuid OR q.availability_scope IS DISTINCT FROM 'staff' OR q.execution_context IS DISTINCT FROM 'staff_simulation' OR combat_consumer_private.staff_test_allowed(q.location_id,array_append(users,auth.uid()),false) IS DISTINCT FROM true)
 AND (mission_factory_owner.human_ordinary_source_v1(p_session,true) IS NULL OR (q.execution_context='staff_simulation' AND combat_consumer_private.staff_test_allowed(q.location_id,array_append(users,auth.uid()),false) IS DISTINCT FROM true)))
THEN RAISE EXCEPTION 'C407_IMMUTABLE_NORMAL_STAFF_HUMAN_SCOPE' USING ERRCODE='42501';END IF;
END $function$

CREATE OR REPLACE FUNCTION mission_factory_owner.c408_stage1_complete_assert_v1()
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN

 IF NOT EXISTS(SELECT 1 FROM pg_proc p JOIN pg_language l ON l.oid=p.prolang WHERE p.oid=to_regprocedure('mission_factory_owner.c416_kind_lease_receipt_immutable_v1()') AND md5(p.prosrc)='e3b1a89bf0565b24e5d280037264489e' AND p.proowner='postgres'::regrole AND p.proacl::text='{postgres=X/postgres}' AND p.prosecdef AND p.provolatile='v' AND p.proconfig=ARRAY['search_path=""']::text[] AND p.prokind='f' AND p.proparallel='u' AND NOT p.proisstrict AND p.provariadic=0 AND p.proargmodes IS NULL AND p.proallargtypes IS NULL AND p.proargdefaults IS NULL AND p.proargnames IS NULL AND p.proargtypes::text='' AND p.prorettype='trigger'::regtype AND NOT p.proretset AND p.pronargdefaults=0 AND l.lanname='plpgsql') THEN RAISE EXCEPTION 'HUMAN27_IMMUTABLE_PROOF_ABI';END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_class t WHERE t.oid='mission_factory_owner.c416_kind_lease_continuity_receipts_v1'::regclass AND t.relowner='postgres'::regrole AND t.relrowsecurity) OR EXISTS(SELECT 1 FROM pg_policy WHERE polrelid='mission_factory_owner.c416_kind_lease_continuity_receipts_v1'::regclass) OR EXISTS(SELECT 1 FROM unnest(ARRAY['anon','authenticated','service_role']) role_name WHERE has_table_privilege(role_name,'mission_factory_owner.c416_kind_lease_continuity_receipts_v1','SELECT,INSERT,UPDATE,DELETE')) OR NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid='mission_factory_owner.c416_kind_lease_continuity_receipts_v1'::regclass AND tgfoid='mission_factory_owner.c416_kind_lease_receipt_immutable_v1()'::regprocedure AND tgname='c416_kind_lease_receipt_immutable' AND tgenabled='O') THEN RAISE EXCEPTION 'HUMAN27_PRIVATE_PROOF_TABLE_GUARD';END IF;

 IF NOT EXISTS(SELECT 1 FROM pg_catalog.pg_proc p JOIN pg_catalog.pg_language l ON l.oid=p.prolang WHERE p.oid=pg_catalog.to_regprocedure('mission_factory_owner.c416_kind_renewal_continuity_v1(uuid,uuid,uuid)') AND md5(p.prosrc)='6506ed9ff5fd3acda1d2c11e22faf602' AND p.proowner='postgres'::regrole AND p.proacl::text='{postgres=X/postgres}' AND p.prosecdef AND p.provolatile='s' AND p.proconfig=ARRAY['search_path=""']::text[] AND p.prokind='f' AND p.proparallel='u' AND NOT p.proisstrict AND p.provariadic=0 AND p.proargmodes IS NULL AND p.proallargtypes IS NULL AND p.proargdefaults IS NULL AND p.prorettype='boolean'::regtype AND NOT p.proretset AND p.pronargdefaults=0 AND p.proargnames=ARRAY['p_draft','p_original_request','p_author']::text[] AND p.proargtypes::text='2950 2950 2950' AND l.lanname='sql') THEN RAISE EXCEPTION 'HUMAN16_CONTINUITY_CERTIFICATE_HELPER_ABI';END IF;
