CREATE OR REPLACE FUNCTION mission_factory_owner.c416_arc_assert_v1(p_arc uuid, p_live boolean)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE a mission_factory_owner.quest_arcs;p mission_factory_owner.publications;
BEGIN
SELECT * INTO STRICT a FROM mission_factory_owner.quest_arcs WHERE id=p_arc;
SELECT * INTO STRICT p FROM mission_factory_owner.publications WHERE request_key=a.publication_request;
PERFORM mission_factory_owner.c416_draft_assert_v1(a.draft_id,p_live);
IF a.source_document->>'content_kind' IS DISTINCT FROM 'quest_human' OR p.content_kind IS DISTINCT FROM 'quest_human' OR p.quest_arc_id IS DISTINCT FROM a.id OR p.source_sha256 IS DISTINCT FROM a.source_sha256 OR a.source_sha256 IS DISTINCT FROM mission_factory_owner.sha(a.source_document) OR ((a.availability_scope IS DISTINCT FROM 'staff' OR a.execution_context IS DISTINCT FROM 'staff_simulation' OR p.target IS DISTINCT FROM 'staff' OR p.state IS DISTINCT FROM 'staff') AND mission_factory_owner.human_ordinary_arc_scope_v1(p_arc,p_live) IS DISTINCT FROM true) THEN RAISE EXCEPTION 'C416_HUMAN_NATIVE_PUBLICATION_REQUIRED';END IF;
END $function$

CREATE OR REPLACE FUNCTION mission_factory_owner.c416_draft_assert_v1(p_draft uuid, p_live boolean)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE d mission_factory_owner.drafts;h mission_factory_owner.c416_human_draft_sources;v mission_factory_owner.c384_authoring_versions;k mission_factory_owner.c416_kind_admission;
BEGIN
SELECT * INTO STRICT d FROM mission_factory_owner.drafts WHERE id=p_draft;
SELECT * INTO STRICT h FROM mission_factory_owner.c416_human_draft_sources WHERE draft_id=p_draft;
SELECT * INTO STRICT v FROM mission_factory_owner.c384_authoring_versions WHERE lineage_id=h.lineage_id AND version=h.authoring_version;
SELECT * INTO STRICT k FROM mission_factory_owner.c416_kind_admission WHERE singleton;
IF d.author_user IS DISTINCT FROM h.author_user OR v.author_user IS DISTINCT FROM h.author_user OR d.control_version IS DISTINCT FROM h.authoring_version OR d.document->>'schema_version' IS DISTINCT FROM 'mission-factory-draft/3' OR d.document->>'content_kind' IS DISTINCT FROM 'quest_human' OR d.document_sha256 IS DISTINCT FROM h.human_document_sha256 OR d.document_sha256 IS DISTINCT FROM mission_factory_owner.sha(d.document) OR v.document_sha256 IS DISTINCT FROM h.dual_source_sha256 OR v.document_sha256 IS DISTINCT FROM mission_factory_owner.sha(v.document) OR v.mechanical_sha256 IS DISTINCT FROM h.mechanical_sha256 OR d.document IS DISTINCT FROM jsonb_set(v.document,'{content_kind}','"quest_human"'::jsonb) OR NOT EXISTS(SELECT 1 FROM mission_factory_owner.quest_roster_assignments r WHERE r.id=h.roster_id AND r.draft_id=d.id AND r.member_character_ids=h.roster AND r.active) THEN RAISE EXCEPTION 'C416_IMMUTABLE_HUMAN_SOURCE_DRIFT';END IF;
IF p_live AND NOT EXISTS(SELECT 1 FROM mission_public_owner.public_qualification_attestations_v1 ordinary_kind WHERE ordinary_kind.request_key=h.kind_admission_request AND (ordinary_kind.payload->>'schema_version'='human-positive-staff-qualification/1' OR (ordinary_kind.payload->>'schema_version'='human-owner-accepted-release/1' AND mission_public_owner.human_positive_qualification_v1(ordinary_kind.release_sha256,true)->>'schema_version'='human-owner-accepted-release/1')) AND ordinary_kind.payload->>'catalog_version'=h.catalog_version AND ordinary_kind.payload->>'catalog_sha256'=h.catalog_sha256 AND EXISTS(SELECT 1 FROM mission_factory_owner.quest_fixed30_admission og WHERE og.singleton AND (og.public_enabled OR (mission_public_owner.human_positive_qualification_v1(ordinary_kind.release_sha256,true)->>'schema_version' IS NOT DISTINCT FROM 'human-owner-accepted-release/1')) AND og.public_release_sha256=ordinary_kind.release_sha256) AND mission_public_owner.human_positive_qualification_v1(ordinary_kind.release_sha256,true) IS NOT NULL) AND NOT EXISTS(SELECT 1 FROM mission_factory_owner.quest_arcs ordinary_arc WHERE ordinary_arc.draft_id=p_draft AND mission_factory_owner.human_ordinary_arc_scope_v1(ordinary_arc.id,true)) AND (mission_factory_owner.c416_kind_live_v1() IS DISTINCT FROM true OR (h.kind_admission_request IS DISTINCT FROM k.request_key AND mission_factory_owner.c416_kind_renewal_continuity_v1(p_draft,h.kind_admission_request,h.author_user) IS DISTINCT FROM true) OR h.catalog_version IS DISTINCT FROM k.catalog_version OR h.catalog_sha256 IS DISTINCT FROM k.catalog_sha256 OR h.author_user<>ALL(k.allowed_auth_ids)) THEN RAISE EXCEPTION 'C416_HUMAN_KIND_ADMISSION_REQUIRED';END IF;
END $function$

