 SET search_path TO ''
AS $function$
DECLARE q mission_factory_owner.quest_run_sources;r public.mission_run_state;m public.master_v2_sessions;d mission_generic_owner.definitions;ph jsonb;opt jsonb;reg mission_factory_owner.quest_decision_registry;he mission_creation_owner.human_encounters;outcome text;why text;base text;decisions jsonb:='[]'::jsonb;started timestamptz;has_role boolean;combat_complete boolean;can_open boolean;
BEGIN
 PERFORM mission_factory_owner.c407_identity_v1(p_session);PERFORM mission_factory_owner.c444_source_read_assert_v1(p_session);
 SELECT * INTO STRICT q FROM mission_factory_owner.quest_run_sources WHERE session_id=p_session;SELECT * INTO STRICT r FROM public.mission_run_state WHERE master_session_id=p_session;SELECT * INTO STRICT m FROM public.master_v2_sessions WHERE id=p_session;SELECT * INTO STRICT d FROM mission_generic_owner.definitions WHERE id=q.definition_id;
 base:=CASE WHEN (NOT mission_factory_owner.c444_enabled_v1() AND mission_factory_owner.human_ordinary_source_v1(p_session,false) IS NULL) OR NOT EXISTS(SELECT 1 FROM mission_factory_owner.c407_control WHERE singleton AND admission_enabled) OR NOT EXISTS(SELECT 1 FROM mission_factory_owner.c412_control WHERE singleton AND runtime_enabled) THEN 'DISABLED' WHEN q.state<>'started' OR m.stato<>'in_corso' OR m.closed_at IS NOT NULL OR m.suspended_at IS NOT NULL OR r.run_phase<>'in_corso' THEN 'NOT_ACTIVE' WHEN EXISTS(SELECT 1 FROM public.mission_run_outbox WHERE master_session_id=p_session AND state IN('pending','human_directed')) THEN 'FATO_PENDING' ELSE 'READY' END;
 SELECT value INTO ph FROM mission_factory_owner.quest_episodes e,LATERAL jsonb_array_elements(e.source_document->'phases')x WHERE e.id=q.episode_id AND value->>'step_key'=r.current_step_key;
 SELECT coalesce(max(e.created_at),r.created_at) INTO started FROM public.mission_run_events e WHERE e.master_session_id=p_session AND e.status='committed' AND e.step_after=r.current_step_key AND e.version_after=r.control_version;
 has_role:=EXISTS(SELECT 1 FROM public.messages msg JOIN public.master_v2_participants p ON p.session_id=p_session AND p.character_id=msg.character_id JOIN public.characters c ON c.id=p.character_id AND c.user_id=p.user_id_snapshot WHERE msg.location_id=m.location_id AND msg.kind='say' AND msg.recipient_user IS NULL AND msg.created_at>=started AND msg.created_at<=statement_timestamp() AND p.joined_at<=msg.created_at AND(p.left_at IS NULL OR p.left_at>msg.created_at));
 SELECT * INTO he FROM mission_creation_owner.human_encounters WHERE master_session_id=p_session AND step_key=r.current_step_key AND run_control_version=r.control_version;
 combat_complete:=he.encounter_id IS NOT NULL AND EXISTS(SELECT 1 FROM public.combat_v2_sessions WHERE id=he.encounter_id AND state IN('risolto','chiuso')) AND (NOT EXISTS(SELECT 1 FROM public.combat_v2_rounds WHERE session_id=he.encounter_id AND state<>'narrato') OR mission_factory_owner.c444_peaceful_complete_v1(p_session,he.encounter_id) IS TRUE);
 IF combat_complete THEN outcome:=mission_creation_owner.combat_outcome(p_session,he.encounter_id);END IF;
 FOR opt IN SELECT value FROM jsonb_array_elements(coalesce(ph->'transition_options','[]'::jsonb)) LOOP
  SELECT * INTO reg FROM mission_factory_owner.quest_decision_registry WHERE catalog_version=d.definition->>'catalog_version' AND catalog_sha256=d.definition->>'catalog_sha256' AND capability_key=ph->>'capability_key' AND decision_key=opt->>'decision_key' AND qualified;
  why:=CASE WHEN base<>'READY' THEN base WHEN reg.decision_key IS NULL THEN 'DECISION_NOT_QUALIFIED' WHEN ph->>'capability_key'='combat.encounter' AND opt->>'decision_key'='combat.peaceful' AND reg.trigger_source_kind='combat_terminal' AND reg.native_combat_outcome='peaceful' AND mission_factory_owner.c444_peaceful_boundary_v1(p_session,he.encounter_id) IS NOT NULL THEN 'READY' WHEN ph->>'capability_key'='combat.encounter' AND NOT combat_complete THEN 'NATIVE_COMBAT_NOT_COMPLETE' WHEN ph->>'capability_key'='combat.encounter' AND(reg.trigger_source_kind IS DISTINCT FROM 'combat_terminal' OR reg.native_combat_outcome IS DISTINCT FROM outcome) THEN 'SERVER_COMBAT_OUTCOME_ROUTE_MISMATCH' WHEN ph->>'capability_key' IN('narrative.scene','terminal.result') AND(reg.trigger_source_kind IS DISTINCT FROM 'narrative_event' OR NOT has_role OR EXISTS(SELECT 1 FROM public.combat_v2_sessions WHERE master_session_id=p_session AND state NOT IN('chiuso','annullato'))) THEN 'NATIVE_ROLE_DIRECTION_REQUIRED' WHEN ph->>'capability_key' NOT IN('narrative.scene','terminal.result','combat.encounter') THEN 'NATIVE_RECEIPT_REQUIRED' WHEN opt->'to_step_key'='null'::jsonb AND ph->>'capability_key'<>'terminal.result' THEN 'TYPED_TERMINAL_OPTION_REQUIRED' ELSE 'READY' END;
  decisions:=decisions||jsonb_build_array(jsonb_build_object('decision_key',opt->>'decision_key','to_step_key',opt->'to_step_key','action',CASE WHEN opt->'to_step_key'='null'::jsonb THEN 'prepare_terminal' ELSE 'advance' END,'can',why='READY','reason_code',why));
 END LOOP;
 can_open:=base='READY' AND ph->>'capability_key'='combat.encounter' AND he.encounter_id IS NULL;
 RETURN jsonb_build_object('schema_version','quest-human-action-scope/1','native_session_id',p_session,'run_control_version',r.control_version,'open_encounter',jsonb_build_object('can',can_open,'reason_code',CASE WHEN can_open THEN 'READY' WHEN base<>'READY' THEN base WHEN he.encounter_id IS NOT NULL THEN 'ENCOUNTER_EXISTS' ELSE 'NOT_COMBAT_PHASE' END),'decisions',decisions);
END $function$

CREATE OR REPLACE FUNCTION mission_factory_owner.c444_enrollment_open_v1(p_episode uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare ep mission_factory_owner.quest_episodes; a mission_factory_owner.quest_arcs;
begin
 IF EXISTS(SELECT 1 FROM mission_factory_owner.quest_episodes oe JOIN mission_factory_owner.quest_arcs oa ON oa.id=oe.arc_id WHERE oe.id=p_episode AND oa.availability_scope='public' AND oa.source_document->>'content_kind'='quest_human') THEN RETURN mission_factory_owner.human_ordinary_enrollment_open_v1(p_episode);END IF;
IF (NOT mission_factory_owner.c444_enabled_v1() OR mission_factory_owner.c416_kind_live_v1() IS DISTINCT FROM true) AND NOT EXISTS(SELECT 1 FROM mission_factory_owner.quest_episodes oe WHERE oe.id=p_episode AND mission_factory_owner.human_ordinary_arc_scope_v1(oe.arc_id,true)) THEN RETURN false;END IF;

 select * into ep from mission_factory_owner.quest_episodes where id=p_episode;
 select * into a from mission_factory_owner.quest_arcs where id=ep.arc_id;
 if ep.id is null or ep.state<>'source_only' or exists(select 1 from mission_factory_owner.quest_run_sources where episode_id=p_episode) then return false;end if;
 if not mission_factory_owner.quest_public_open_v3(a.id) then return false;end if;
 if mission_factory_owner.quest_publication_scope_v3(a.id,true) not in('staff','public') then return false;end if;
 if ep.ordinal=1 then return a.state in('staff_source','public_source');end if;
 return a.quest_kind='trama' and a.state='in_progress' and exists(
   select 1 from mission_factory_owner.quest_episodes prev
   join mission_factory_owner.quest_run_sources q on q.episode_id=prev.id and q.state='terminal'
   join mission_factory_owner.quest_terminal_receipts tr on tr.id=q.terminal_receipt_id
   where prev.arc_id=a.id and prev.ordinal=ep.ordinal-1
     and mission_factory_owner.quest_terminal_confirmed_v1(q.session_id) is not null);
end $function$

CREATE OR REPLACE FUNCTION mission_factory_owner.c444_enrollment_v1(p_episode uuid, p_operation text, p_ready boolean, p_expected_version bigint, p_request uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare uid uuid:=auth.uid(); c public.characters%rowtype;
  e mission_factory_owner.quest_episodes%rowtype;
  a mission_factory_owner.quest_arcs%rowtype;
  pub mission_factory_owner.publications%rowtype;
  x mission_factory_owner.quest_episode_enrollments%rowtype;
  old mission_factory_owner.quest_episode_enrollment_requests%rowtype;
  fp text; receipt jsonb;
begin
PERFORM mission_factory_owner.c444_episode_read_assert_v1(p_episode);

  if uid is null or p_episode is null or p_request is null
     or p_operation is null or p_operation not in ('join','withdraw','ready')
     or (p_operation='ready' and p_ready is null)
     or (p_operation<>'ready' and p_ready is not null)
     or (p_operation='join' and p_expected_version is not null)
     or (p_operation in ('withdraw','ready') and
         (p_expected_version is null or p_expected_version<1))
  then raise exception 'MF_QUEST_ENROLLMENT_INPUT' using errcode='22023'; end if;
  select * into strict c from public.characters where user_id=uid;
  perform pg_advisory_xact_lock(hashtextextended(p_request::text,25092601));
  fp:=mission_factory_owner.sha(jsonb_build_object('episode',p_episode,
    'operation',p_operation,'character',c.id,'ready',p_ready,
    'expected_version',p_expected_version));
  select * into old from mission_factory_owner.quest_episode_enrollment_requests
    where request_key=p_request for share;
  if found then
    if old.actor_user<>uid or old.episode_id<>p_episode
       or old.character_id<>c.id or old.operation<>p_operation
       or old.request_fingerprint<>fp
    then raise exception 'MF_QUEST_ENROLLMENT_REQUEST_CONFLICT' using errcode='23505'; end if;
    return old.result;
  end if;
  IF NOT mission_factory_owner.c444_enabled_v1() AND NOT EXISTS(SELECT 1 FROM mission_factory_owner.quest_episodes oe WHERE oe.id=p_episode AND mission_factory_owner.human_ordinary_arc_scope_v1(oe.arc_id,true)) THEN RAISE EXCEPTION 'C444_RUNTIME_OFF';END IF;
  PERFORM mission_factory_owner.c416_arc_assert_v1((SELECT arc_id FROM mission_factory_owner.quest_episodes WHERE id=p_episode),true);
  select * into strict a from mission_factory_owner.quest_arcs
    where id=(select arc_id from mission_factory_owner.quest_episodes where id=p_episode) for share;
  select * into strict e from mission_factory_owner.quest_episodes
    where id=p_episode and arc_id=a.id for update;
  select * into strict pub from mission_factory_owner.publications
    where request_key=a.publication_request for share;
  if not mission_factory_owner.c444_enrollment_open_v1(e.id)
     or pub.content_kind<>'quest_human' or not mission_factory_owner.quest_public_open_v3(a.id)
     or pub.quest_arc_id<>a.id
     or e.source_sha256<>mission_factory_owner.sha(e.source_document)
     or not(c.id=any(e.member_character_ids)) or c.user_id is distinct from uid
     or exists(select 1 from mission_factory_owner.quest_run_sources
       where episode_id=p_episode)
  then raise exception 'MF_QUEST_ENROLLMENT_CLOSED' using errcode='55000'; end if;
  perform pg_advisory_xact_lock(hashtextextended(c.id::text,203));
  select * into x from mission_factory_owner.quest_episode_enrollments
    where episode_id=p_episode and character_id=c.id for update;
  if p_operation='join' then
    if x.character_id is null or x.state='withdrawn' then
      if exists(select 1 from public.mission_bookings b
          join public.missions m on m.id=b.mission_id
          where b.character_id=c.id and b.status='iscritto'
            and m.status in ('aperta','programmata'))
         or exists(select 1 from public.master_v2_participants mp
           join public.master_v2_sessions ms on ms.id=mp.session_id
           where mp.character_id=c.id and mp.left_at is null and ms.closed_at is null)
         or exists(select 1 from mission_ai_board_owner.roster_reservations rr
           where rr.character_id=c.id and rr.state='active')
      then raise exception 'MF_QUEST_CHARACTER_BUSY' using errcode='40001'; end if;
    end if;
    if x.character_id is null then
      insert into mission_factory_owner.quest_episode_enrollments(
        episode_id,character_id,user_id_snapshot,source_sha256,
        roster_assignment_id,state)
      values(p_episode,c.id,uid,e.source_sha256,e.roster_assignment_id,'joined')
      returning * into x;
    elsif x.user_id_snapshot<>uid or x.source_sha256<>e.source_sha256
       or x.roster_assignment_id<>e.roster_assignment_id
    then raise exception 'MF_QUEST_ENROLLMENT_SOURCE_DRIFT' using errcode='40001';
    elsif x.state='withdrawn' then
      update mission_factory_owner.quest_episode_enrollments
        set state='joined',ready=false,ready_at=null,
          control_version=control_version+1,joined_at=clock_timestamp(),
          changed_at=clock_timestamp()
        where episode_id=p_episode and character_id=c.id returning * into x;
    end if;
  else
    if x.character_id is null or x.user_id_snapshot<>uid or x.state<>'joined'
    then raise exception 'MF_QUEST_NOT_JOINED' using errcode='55000'; end if;
    if x.control_version<>p_expected_version
    then raise exception 'MF_QUEST_ENROLLMENT_CAS' using errcode='40001'; end if;
    if p_operation='withdraw' then
      update mission_factory_owner.quest_episode_enrollments
        set state='withdrawn',ready=false,ready_at=null,
          control_version=control_version+1,changed_at=clock_timestamp()
        where episode_id=p_episode and character_id=c.id returning * into x;
    else
      update mission_factory_owner.quest_episode_enrollments
        set ready=p_ready,ready_at=case when p_ready then clock_timestamp() else null end,
          control_version=control_version+1,changed_at=clock_timestamp()
        where episode_id=p_episode and character_id=c.id returning * into x;
    end if;
  end if;
  receipt:=jsonb_build_object('schema_version','quest-episode-enrollment/1',
    'request_key',p_request,'quest_episode_id',p_episode,'character_id',c.id,
    'source_sha256',x.source_sha256,'roster_assignment_id',x.roster_assignment_id,
    'state',x.state,'ready',x.ready,'control_version',x.control_version);
  insert into mission_factory_owner.quest_episode_enrollment_requests(
    request_key,episode_id,character_id,actor_user,operation,request_fingerprint,result)
  values(p_request,p_episode,c.id,uid,p_operation,fp,receipt);
  return receipt;
end; $function$

CREATE OR REPLACE FUNCTION mission_factory_owner.c444_peaceful_boundary_v1(p_session uuid, p_encounter uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE m public.master_v2_sessions;q mission_factory_owner.quest_run_sources;r public.mission_run_state;he mission_creation_owner.human_encounters;rr public.combat_v2_rounds;rep public.combat_v2_round_reports;w mission_generic_owner.regia_human_windows_v1;abandoned uuid;ph jsonb;opt jsonb;d mission_generic_owner.definitions;
BEGIN
 IF mission_factory_owner.human_ordinary_source_v1(p_session,true) IS NOT NULL THEN RETURN mission_factory_owner.human_ordinary_peaceful_boundary_v1(p_session,p_encounter);END IF;
 IF NOT mission_factory_owner.c395_human_mode_v1(p_session) THEN RETURN NULL;END IF;
 PERFORM mission_factory_owner.c407_identity_v1(p_session);PERFORM mission_factory_owner.c444_source_read_assert_v1(p_session);
 SELECT * INTO STRICT m FROM public.master_v2_sessions WHERE id=p_session;
 SELECT * INTO STRICT q FROM mission_factory_owner.quest_run_sources WHERE session_id=p_session;
 SELECT * INTO STRICT r FROM public.mission_run_state WHERE master_session_id=p_session;
 IF auth.uid() IS DISTINCT FROM m.master_user OR public.is_staff() IS DISTINCT FROM true OR NOT public.master_v2_is_master(auth.uid())
 OR m.owner_kind<>'human' OR m.tipo<>'quest' OR m.mission_id IS NOT NULL OR m.stato<>'in_corso' OR m.closed_at IS NOT NULL OR m.suspended_at IS NOT NULL
 OR m.location_id<>'0b85f354-9cdb-47e1-baf9-3d266bb7e06b'::uuid OR q.state<>'started' OR q.execution_context<>'staff_simulation' OR q.availability_scope<>'staff' OR r.source_kind<>'quest' OR r.run_phase<>'in_corso'
 OR NOT EXISTS(SELECT 1 FROM mission_factory_owner.c416_kind_admission WHERE singleton AND enabled AND allowed_auth_ids=ARRAY['f0856d53-83a6-4de0-bc0c-12c87916e665','b4952ed5-5ce0-49c0-9f2b-8fd5dcd89b4b']::uuid[] AND expires_at>statement_timestamp())
 OR NOT EXISTS(SELECT 1 FROM mission_factory_owner.c463_optin_control WHERE singleton AND enabled AND p_session=ANY(session_ids) AND m.master_user=ANY(master_user_ids) AND expires_at>statement_timestamp())
 OR EXISTS(SELECT 1 FROM public.mission_run_outbox WHERE master_session_id=p_session AND state IN('pending','human_directed'))
 THEN RETURN NULL;END IF;
 SELECT * INTO he FROM mission_creation_owner.human_encounters WHERE master_session_id=p_session AND encounter_id=p_encounter AND step_key=r.current_step_key AND run_control_version=r.control_version;
 IF NOT FOUND OR NOT EXISTS(SELECT 1 FROM public.combat_v2_sessions WHERE id=p_encounter AND master_session_id=p_session AND state='in_corso' AND closed_at IS NULL)
 OR combat_panel_private.uses_simulated_pools(p_encounter) IS DISTINCT FROM true OR public.combat_v2_values_written(p_encounter) IS DISTINCT FROM false
 OR EXISTS(SELECT 1 FROM public.combat_v2_resource_ledger WHERE session_id=p_encounter AND NOT is_simulated) THEN RETURN NULL;END IF;
 SELECT * INTO STRICT d FROM mission_generic_owner.definitions WHERE id=q.definition_id;
 SELECT value INTO ph FROM mission_factory_owner.quest_episodes e,LATERAL jsonb_array_elements(e.source_document->'phases')x WHERE e.id=q.episode_id AND value->>'step_key'=r.current_step_key;
 IF ph->>'capability_key' IS DISTINCT FROM 'combat.encounter' THEN RETURN NULL;END IF;
 SELECT value INTO opt FROM jsonb_array_elements(ph->'transition_options')x WHERE value->>'decision_key'='combat.peaceful';
 IF opt IS NULL OR opt->'to_step_key'='null'::jsonb OR NOT EXISTS(SELECT 1 FROM mission_factory_owner.quest_decision_registry WHERE catalog_version=d.definition->>'catalog_version' AND catalog_sha256=d.definition->>'catalog_sha256' AND capability_key='combat.encounter' AND decision_key='combat.peaceful' AND qualified AND trigger_source_kind='combat_terminal' AND native_combat_outcome='peaceful') THEN RETURN NULL;END IF;
 SELECT * INTO rr FROM public.combat_v2_rounds WHERE session_id=p_encounter ORDER BY round_no DESC LIMIT 1;
 IF NOT FOUND THEN RETURN NULL;END IF;
 IF rr.state='raccolta_azioni' AND rr.phase='raccolta_azioni' AND rr.report_id IS NULL AND rr.freeze_at IS NULL AND rr.resolved_at IS NULL AND rr.narrated_at IS NULL THEN
 abandoned:=rr.id;
 IF EXISTS(SELECT 1 FROM public.combat_v2_declarations WHERE round_id=rr.id) OR EXISTS(SELECT 1 FROM public.combat_v2_round_reports WHERE round_id=rr.id)
 OR EXISTS(SELECT 1 FROM public.combat_v2_resource_ledger WHERE round_id=rr.id) OR EXISTS(SELECT 1 FROM public.combat_v2_ratings WHERE round_id=rr.id)
 OR EXISTS(SELECT 1 FROM public.combat_v2_attack_targets WHERE round_id=rr.id) OR EXISTS(SELECT 1 FROM public.combat_v2_defense_coverages WHERE round_id=rr.id)
 OR EXISTS(SELECT 1 FROM public.combat_v2_narratives WHERE round_id=rr.id) OR EXISTS(SELECT 1 FROM public.combat_v2_ai_narrative_previews WHERE round_id=rr.id)
 OR EXISTS(SELECT 1 FROM combat_panel_private.actor_turns WHERE round_id=rr.id AND (main_declaration_id IS NOT NULL OR state<>'ready')) THEN RETURN NULL;END IF;
 SELECT * INTO rr FROM public.combat_v2_rounds WHERE session_id=p_encounter AND id<>abandoned ORDER BY round_no DESC LIMIT 1;
 END IF;
 IF rr.id IS NULL OR rr.state<>'narrato' OR rr.report_id IS NULL OR EXISTS(SELECT 1 FROM public.combat_v2_rounds other WHERE other.session_id=p_encounter AND other.state<>'narrato' AND (abandoned IS NULL OR other.id<>abandoned)) THEN RETURN NULL;END IF;
 SELECT * INTO rep FROM public.combat_v2_round_reports WHERE id=rr.report_id AND round_id=rr.id AND narration_state='pubblicata' AND message_id IS NOT NULL AND values_written=false;
 IF NOT FOUND THEN RETURN NULL;END IF;
 SELECT * INTO w FROM mission_generic_owner.regia_human_windows_v1 WHERE master_session_id=p_session AND encounter_id=p_encounter AND source_round_id=rr.id AND source_report_id=rep.id AND source_report_sha256=rep.mechanics_sha256 AND state='published' AND message_id=rep.message_id AND publication_id=rep.message_id;
 IF NOT FOUND OR NOT EXISTS(SELECT 1 FROM public.messages msg WHERE msg.id=w.message_id AND msg.location_id=m.location_id AND msg.kind='fato' AND public.combat_v2_sha256(jsonb_build_object('body',msg.body))=w.publication_body_sha256) THEN RETURN NULL;END IF;
 RETURN jsonb_build_object('encounter_id',p_encounter,'run_version',r.control_version,'step_key',r.current_step_key,'source_sha256',q.source_sha256,'narrated_round_id',rr.id,'report_id',rep.id,'report_sha256',rep.mechanics_sha256,'fato_message_id',w.message_id,'fato_sha256',w.publication_body_sha256,'abandoned_round_id',abandoned,'decision_key','combat.peaceful','to_step_key',opt->>'to_step_key');
END
$function$

CREATE OR REPLACE FUNCTION mission_factory_owner.c444_peaceful_complete_v1(p_session uuid, p_encounter uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE proof mission_factory_owner.c444_peaceful_native_receipts_v1;q mission_factory_owner.quest_run_sources;r public.mission_run_state;m public.master_v2_sessions;ev public.combat_v2_events;
BEGIN
 IF mission_factory_owner.human_ordinary_source_v1(p_session,true) IS NOT NULL THEN RETURN mission_factory_owner.human_ordinary_peaceful_complete_v1(p_session,p_encounter);END IF;
 IF NOT mission_factory_owner.c395_human_mode_v1(p_session) THEN RETURN false;END IF;
 PERFORM mission_factory_owner.c407_identity_v1(p_session);PERFORM mission_factory_owner.c444_source_read_assert_v1(p_session);
 SELECT * INTO proof FROM mission_factory_owner.c444_peaceful_native_receipts_v1 WHERE session_id=p_session AND encounter_id=p_encounter;
 IF NOT FOUND THEN RETURN false;END IF;
 SELECT * INTO STRICT q FROM mission_factory_owner.quest_run_sources WHERE session_id=p_session;
 SELECT * INTO STRICT r FROM public.mission_run_state WHERE master_session_id=p_session;
 SELECT * INTO STRICT m FROM public.master_v2_sessions WHERE id=p_session;
 SELECT * INTO ev FROM public.combat_v2_events WHERE id=proof.event_id;
 IF m.location_id<>'0b85f354-9cdb-47e1-baf9-3d266bb7e06b'::uuid OR q.execution_context<>'staff_simulation' OR q.availability_scope<>'staff'
 OR proof.source_sha256 IS DISTINCT FROM q.source_sha256 OR proof.run_version IS DISTINCT FROM r.control_version OR proof.step_key IS DISTINCT FROM r.current_step_key
 OR proof.actor_user IS DISTINCT FROM m.master_user OR ev.scope_id IS DISTINCT FROM p_session OR ev.caller IS DISTINCT FROM proof.actor_user OR ev.caller_kind IS DISTINCT FROM 'human' OR ev.caller_service_capability IS NOT NULL
 OR ev.request_key IS DISTINCT FROM extensions.uuid_generate_v5(proof.request_key,'human-combat-close') OR ev.status IS DISTINCT FROM 'completata' OR ev.operation_kind IS DISTINCT FROM 'mission_human_combat_close' OR public.combat_v2_sha256(to_jsonb(ev)) IS DISTINCT FROM proof.event_sha256
 OR ev.result#>>'{data,outcome}' IS DISTINCT FROM 'peaceful' OR ev.result#>>'{data,encounter_id}' IS DISTINCT FROM p_encounter::text
 OR ev.result#>>'{data,step_key}' IS DISTINCT FROM proof.step_key OR ev.result#>>'{data,run_version}' IS DISTINCT FROM proof.run_version::text
 OR NOT EXISTS(SELECT 1 FROM public.combat_v2_sessions WHERE id=p_encounter AND master_session_id=p_session AND state='chiuso' AND closed_at IS NOT NULL)
 OR NOT EXISTS(SELECT 1 FROM public.combat_v2_rounds rr JOIN public.combat_v2_round_reports rep ON rep.id=rr.report_id
