CREATE OR REPLACE FUNCTION mission_factory_owner.c444_peaceful_history_complete_v1(p_session uuid, p_encounter uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE proof mission_factory_owner.c444_peaceful_native_receipts_v1;q mission_factory_owner.quest_run_sources;r public.mission_run_state;m public.master_v2_sessions;ev public.combat_v2_events;he mission_creation_owner.human_encounters;ph jsonb;
BEGIN
 IF mission_factory_owner.human_ordinary_source_v1(p_session,true) IS NOT NULL THEN RETURN mission_factory_owner.human_ordinary_peaceful_history_complete_v1(p_session,p_encounter);END IF;
 IF NOT mission_factory_owner.c395_human_mode_v1(p_session) THEN RETURN false;END IF;
 PERFORM mission_factory_owner.c407_identity_v1(p_session);PERFORM mission_factory_owner.c444_source_read_assert_v1(p_session);
 SELECT * INTO proof FROM mission_factory_owner.c444_peaceful_native_receipts_v1 WHERE session_id=p_session AND encounter_id=p_encounter;
 IF NOT FOUND THEN RETURN false;END IF;
 SELECT * INTO STRICT q FROM mission_factory_owner.quest_run_sources WHERE session_id=p_session;
 SELECT * INTO STRICT r FROM public.mission_run_state WHERE master_session_id=p_session;
 SELECT * INTO STRICT m FROM public.master_v2_sessions WHERE id=p_session;
 SELECT * INTO ev FROM public.combat_v2_events WHERE id=proof.event_id;
 SELECT * INTO he FROM mission_creation_owner.human_encounters WHERE master_session_id=p_session AND encounter_id=p_encounter;
 IF NOT FOUND THEN RETURN false;END IF;
 SELECT value INTO ph FROM mission_factory_owner.quest_episodes e,LATERAL jsonb_array_elements(e.source_document->'phases') x WHERE e.id=q.episode_id AND value->>'step_key'=r.current_step_key;
 IF auth.uid() IS DISTINCT FROM m.master_user OR public.is_staff() IS DISTINCT FROM true OR NOT public.master_v2_is_master(auth.uid())
 OR m.owner_kind<>'human' OR m.tipo<>'quest' OR m.mission_id IS NOT NULL OR m.stato<>'in_corso' OR m.closed_at IS NOT NULL OR m.suspended_at IS NOT NULL
 OR q.state<>'started' OR r.source_kind<>'quest' OR r.run_phase<>'in_corso'
 OR ph->>'capability_key' IS DISTINCT FROM 'terminal.result' OR r.control_version IS DISTINCT FROM proof.run_version+1 OR r.current_step_key IS NOT DISTINCT FROM proof.step_key
 OR NOT EXISTS(SELECT 1 FROM public.mission_run_events te WHERE te.id=r.last_event_id AND te.master_session_id=p_session AND te.operation_kind='transition' AND te.status='committed' AND te.version_before=proof.run_version AND te.version_after=r.control_version AND te.step_after=r.current_step_key AND te.request_key_sha256=mission_internal.request_key_sha256(proof.request_key))
 OR NOT EXISTS(SELECT 1 FROM mission_factory_owner.c416_kind_admission WHERE singleton AND enabled AND allowed_auth_ids=ARRAY['f0856d53-83a6-4de0-bc0c-12c87916e665','b4952ed5-5ce0-49c0-9f2b-8fd5dcd89b4b']::uuid[] AND expires_at>statement_timestamp())
 OR NOT EXISTS(SELECT 1 FROM mission_factory_owner.c463_optin_control WHERE singleton AND enabled AND p_session=ANY(session_ids) AND m.master_user=ANY(master_user_ids) AND expires_at>statement_timestamp())
 OR NOT EXISTS(SELECT 1 FROM mission_factory_owner.c444_runtime_control WHERE singleton AND enabled AND expires_at>statement_timestamp())
 THEN RETURN false;END IF;

 IF m.location_id<>'0b85f354-9cdb-47e1-baf9-3d266bb7e06b'::uuid OR q.execution_context<>'staff_simulation' OR q.availability_scope<>'staff'
 OR proof.source_sha256 IS DISTINCT FROM q.source_sha256 OR proof.run_version IS DISTINCT FROM he.run_control_version OR proof.step_key IS DISTINCT FROM he.step_key
 OR proof.actor_user IS DISTINCT FROM m.master_user OR ev.scope_id IS DISTINCT FROM p_session OR ev.caller IS DISTINCT FROM proof.actor_user OR ev.caller_kind IS DISTINCT FROM 'human' OR ev.caller_service_capability IS NOT NULL
 OR ev.request_key IS DISTINCT FROM extensions.uuid_generate_v5(proof.request_key,'human-combat-close') OR ev.status IS DISTINCT FROM 'completata' OR ev.operation_kind IS DISTINCT FROM 'mission_human_combat_close' OR public.combat_v2_sha256(to_jsonb(ev)) IS DISTINCT FROM proof.event_sha256
 OR ev.result#>>'{data,outcome}' IS DISTINCT FROM 'peaceful' OR ev.result#>>'{data,encounter_id}' IS DISTINCT FROM p_encounter::text
 OR ev.result#>>'{data,step_key}' IS DISTINCT FROM proof.step_key OR ev.result#>>'{data,run_version}' IS DISTINCT FROM proof.run_version::text
 OR NOT EXISTS(SELECT 1 FROM public.combat_v2_sessions WHERE id=p_encounter AND master_session_id=p_session AND state='chiuso' AND closed_at IS NOT NULL)
 OR NOT EXISTS(SELECT 1 FROM public.combat_v2_rounds rr JOIN public.combat_v2_round_reports rep ON rep.id=rr.report_id
 WHERE rr.id=proof.narrated_round_id AND rr.session_id=p_encounter AND rr.state='narrato' AND rep.id=proof.report_id AND rep.mechanics_sha256=proof.report_sha256
 AND rep.narration_state='pubblicata' AND rep.message_id=proof.fato_message_id)
 OR NOT EXISTS(SELECT 1 FROM public.messages msg WHERE msg.id=proof.fato_message_id AND msg.location_id=m.location_id AND msg.kind='fato' AND public.combat_v2_sha256(jsonb_build_object('body',msg.body))=proof.fato_sha256)
 OR EXISTS(SELECT 1 FROM public.combat_v2_resource_ledger WHERE session_id=p_encounter AND NOT is_simulated)
 OR EXISTS(SELECT 1 FROM public.combat_v2_rounds rr WHERE rr.session_id=p_encounter AND rr.state<>'narrato' AND (proof.abandoned_round_id IS NULL OR rr.id<>proof.abandoned_round_id))
 THEN RETURN false;END IF;
 IF proof.abandoned_round_id IS NOT NULL AND (
 NOT EXISTS(SELECT 1 FROM public.combat_v2_rounds WHERE id=proof.abandoned_round_id AND session_id=p_encounter AND state='raccolta_azioni' AND phase='raccolta_azioni' AND report_id IS NULL AND freeze_at IS NULL AND resolved_at IS NULL AND narrated_at IS NULL)
 OR EXISTS(SELECT 1 FROM public.combat_v2_declarations WHERE round_id=proof.abandoned_round_id)
 OR EXISTS(SELECT 1 FROM public.combat_v2_round_reports WHERE round_id=proof.abandoned_round_id)
 OR EXISTS(SELECT 1 FROM public.combat_v2_resource_ledger WHERE round_id=proof.abandoned_round_id)
 OR EXISTS(SELECT 1 FROM public.combat_v2_ratings WHERE round_id=proof.abandoned_round_id)
 OR EXISTS(SELECT 1 FROM public.combat_v2_attack_targets WHERE round_id=proof.abandoned_round_id)
 OR EXISTS(SELECT 1 FROM public.combat_v2_defense_coverages WHERE round_id=proof.abandoned_round_id)
 OR EXISTS(SELECT 1 FROM public.combat_v2_narratives WHERE round_id=proof.abandoned_round_id)
 OR EXISTS(SELECT 1 FROM public.combat_v2_ai_narrative_previews WHERE round_id=proof.abandoned_round_id)
 OR EXISTS(SELECT 1 FROM combat_panel_private.actor_turns WHERE round_id=proof.abandoned_round_id AND (main_declaration_id IS NOT NULL OR state<>'ready'))
 ) THEN RETURN false;END IF;
 RETURN true;
END
