CREATE OR REPLACE FUNCTION mission_factory_owner.c444_source_read_assert_v1(p_session uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare q mission_factory_owner.quest_run_sources%rowtype;
m public.master_v2_sessions%rowtype;
e mission_factory_owner.quest_episodes%rowtype;
a mission_factory_owner.quest_arcs%rowtype;
pub mission_factory_owner.publications%rowtype;
p public.mission_plans%rowtype;
v public.mission_plan_versions%rowtype;
d mission_generic_owner.definitions%rowtype;
b mission_generic_owner.run_bindings%rowtype;
loc public.locations%rowtype;
users uuid[];
begin

PERFORM mission_factory_owner.c444_read_identity_v1(p_session);
PERFORM mission_factory_owner.c412_revision_provenance_v1(p_session);
select * into strict q from mission_factory_owner.quest_run_sources where session_id=p_session;
select * into strict m from public.master_v2_sessions where id=p_session;
select * into strict e from mission_factory_owner.quest_episodes where id=q.episode_id;
select * into strict a from mission_factory_owner.quest_arcs where id=q.arc_id;
select * into strict pub from mission_factory_owner.publications
where request_key=a.publication_request;
select * into strict p from public.mission_plans where id=q.plan_id;
select * into strict v from public.mission_plan_versions where id=q.plan_version_id;
select * into strict d from mission_generic_owner.definitions where id=q.definition_id;
select * into strict b from mission_generic_owner.run_bindings where master_session_id=p_session;
select * into strict loc from public.locations where id=q.location_id;
select array_agg(c.user_id order by x.ord) into users
from unnest(q.roster_character_ids) with ordinality x(id,ord)
join public.characters c on c.id=x.id and c.user_id is not null;
if m.tipo<>'quest' or m.owner_kind<>'human' or m.master_user IS DISTINCT FROM (SELECT assigned_master FROM mission_factory_owner.c384_human_bindings WHERE session_id=p_session)
or m.mission_id is not null or m.quest_kind is distinct from a.quest_kind
or m.location_id<>q.location_id
or (q.state not in ('terminal','cancelled') and m.stato in ('chiusa','annullata'))
or e.arc_id<>q.arc_id or e.source_sha256<>q.source_sha256 or e.ordinal<>q.episode_ordinal or e.member_character_ids is distinct from q.roster_character_ids
or (q.episode_ordinal>1 and not exists(select 1 from mission_factory_owner.quest_terminal_receipts tr
join mission_factory_owner.quest_episodes pe on pe.id=tr.episode_id
join mission_factory_owner.quest_run_sources pq on pq.episode_id=pe.id and pq.terminal_receipt_id=tr.id
where tr.id=q.previous_episode_terminal_receipt_id and pe.arc_id=q.arc_id and pe.ordinal=q.episode_ordinal-1
and pq.state='terminal' and tr.continuity_private_sha256=q.continuity_sha256
and tr.continuity_private_sha256=mission_factory_owner.sha(tr.continuity_private)))
or (q.state='prepared' and e.state<>'source_only')
or (q.state in('opening_pending','uncertain','started')
and e.state not in('source_only','open','in_progress'))
or a.state not in ('staff_source','public_source','in_progress','completed','failed')
or pub.content_kind<>'quest_human' or not mission_factory_owner.quest_public_open_v3(a.id)
or pub.quest_arc_id<>q.arc_id
or pub.release_revision_sha256 is distinct from q.staff_release_sha256
or p.source_kind<>'quest' or p.quest_episode_id<>q.episode_id
or p.quest_source_sha256<>q.source_sha256
or p.mission_id is not null or v.plan_id<>q.plan_id or v.stato<>'approvata'
or v.plan_sha256<>q.plan_sha256
or d.plan_version_id<>q.plan_version_id or d.plan_sha256<>q.plan_sha256
or d.definition_sha256<>q.definition_sha256
or d.definition_sha256<>mission_internal.fingerprint(d.definition)
or d.definition->>'schema_version'<>'mission-factory-quest-definition/1'
or d.definition->>'quest_episode_id' is distinct from q.episode_id::text
or d.definition->>'source_sha256' is distinct from q.source_sha256
or b.definition_id is distinct from q.definition_id
or b.snapshot is distinct from mission_factory_owner.c395_binding_projection_v1(q)
or b.snapshot_sha256 is distinct from mission_internal.fingerprint(b.snapshot)
or q.roster_snapshot_sha256<>mission_factory_owner.sha(to_jsonb(q.roster_character_ids))
or cardinality(users)<>cardinality(q.roster_character_ids)
or (select count(distinct x) from unnest(q.roster_character_ids)x)<>cardinality(q.roster_character_ids)
or not loc.is_active or loc.is_test is distinct from mission_factory_owner.quest_is_simulation_v4(q.arc_id) or (not mission_factory_owner.quest_is_simulation_v4(q.arc_id) and loc.is_exam_room)
or (mission_factory_owner.quest_is_simulation_v4(q.arc_id) and not combat_consumer_private.staff_test_allowed(q.location_id,users,false))
or q.execution_context is distinct from a.execution_context or q.execution_qualification_sha256 is distinct from a.execution_qualification_sha256
or (a.execution_context='staff_simulation' and a.availability_scope='public' and (q.location_id<>'0b85f354-9cdb-47e1-baf9-3d266bb7e06b'::uuid or exists(select 1 from public.characters c where c.id=any(q.roster_character_ids) and not(c.user_id=any(a.execution_auth_ids)))))
or q.availability_scope is distinct from a.availability_scope or q.public_release_sha256 is distinct from a.public_release_sha256
then raise exception 'MF_QUEST_RUN_SOURCE_STALE' using errcode='42501'; end if;
if q.availability_scope='public' then perform mission_factory_owner.human_ordinary_execution_read_assert_v1(a.id,q.state not in('terminal','cancelled'));end if;
return jsonb_build_object('schema_version','quest-run-source/1',
'session_id',q.session_id,'arc_id',q.arc_id,'episode_id',q.episode_id,
'source_sha256',q.source_sha256,'plan_version_id',q.plan_version_id,
'plan_sha256',q.plan_sha256,'roster_snapshot_sha256',q.roster_snapshot_sha256,
'staff_release_sha256',q.staff_release_sha256,'location_id',q.location_id,
'state',q.state,'control_version',q.control_version);
end $function$

CREATE OR REPLACE FUNCTION mission_factory_owner.c444_terminal_participants_finish_v1(p_session uuid, p_receipt uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE m public.master_v2_sessions;q mission_factory_owner.quest_run_sources;tr mission_factory_owner.quest_terminal_receipts;receipt jsonb;users uuid[];locked_location uuid;affected integer;
BEGIN
 IF mission_factory_owner.human_ordinary_source_v1(p_session,true) IS NOT NULL THEN RETURN mission_factory_owner.human_ordinary_participants_finish_v1(p_session,p_receipt);END IF;
 IF p_session IS NULL OR p_receipt IS NULL OR auth.role() IS DISTINCT FROM 'authenticated' OR auth.uid() IS NULL THEN RAISE EXCEPTION 'HUMAN34_PARTICIPANTS_INPUT' USING ERRCODE='42501';END IF;
 PERFORM mission_factory_owner.c407_identity_v1(p_session);
 SELECT location_id INTO STRICT locked_location FROM mission_factory_owner.quest_run_sources WHERE session_id=p_session;
 PERFORM 1 FROM public.locations WHERE id=locked_location FOR UPDATE;
 PERFORM public.master_v2_lock_scope(p_session);
 SELECT * INTO STRICT m FROM public.master_v2_sessions WHERE id=p_session FOR UPDATE;
 SELECT * INTO STRICT q FROM mission_factory_owner.quest_run_sources WHERE session_id=p_session FOR SHARE;
 SELECT * INTO STRICT tr FROM mission_factory_owner.quest_terminal_receipts WHERE id=p_receipt AND session_id=p_session FOR SHARE;
 SELECT array_agg(c.user_id ORDER BY x.ord) INTO users FROM unnest(q.roster_character_ids) WITH ORDINALITY x(id,ord) JOIN public.characters c ON c.id=x.id;
 IF mission_factory_owner.c395_human_mode_v1(p_session) IS DISTINCT FROM true OR auth.uid() IS DISTINCT FROM m.master_user OR public.is_staff() IS DISTINCT FROM true OR public.master_v2_is_master(auth.uid()) IS DISTINCT FROM true
 OR m.owner_kind IS DISTINCT FROM 'human' OR m.tipo IS DISTINCT FROM 'quest' OR m.mission_id IS NOT NULL OR m.stato IS DISTINCT FROM 'chiusa' OR m.closed_at IS NULL OR m.suspended_at IS NOT NULL
 OR m.location_id IS DISTINCT FROM locked_location OR q.location_id IS DISTINCT FROM '0b85f354-9cdb-47e1-baf9-3d266bb7e06b'::uuid OR q.availability_scope IS DISTINCT FROM 'staff' OR q.execution_context IS DISTINCT FROM 'staff_simulation'
 OR q.state IS DISTINCT FROM 'terminal' OR q.terminal_receipt_id IS DISTINCT FROM p_receipt OR tr.episode_id IS DISTINCT FROM q.episode_id OR tr.source_sha256 IS DISTINCT FROM q.source_sha256
 OR cardinality(q.roster_character_ids) IS DISTINCT FROM 2 OR cardinality(users) IS DISTINCT FROM 2 OR(SELECT count(DISTINCT u) FROM unnest(users)u)<>2 OR EXISTS(SELECT 1 FROM unnest(users)u WHERE NOT(u=ANY(ARRAY['f0856d53-83a6-4de0-bc0c-12c87916e665','b4952ed5-5ce0-49c0-9f2b-8fd5dcd89b4b']::uuid[]))) OR q.roster_snapshot_sha256 IS DISTINCT FROM mission_factory_owner.sha(to_jsonb(q.roster_character_ids))
 OR combat_consumer_private.staff_test_allowed(q.location_id,array_append(users,auth.uid()),false) IS DISTINCT FROM true
 OR NOT EXISTS(SELECT 1 FROM mission_factory_owner.c416_kind_admission WHERE singleton AND enabled AND allowed_auth_ids=ARRAY['f0856d53-83a6-4de0-bc0c-12c87916e665','b4952ed5-5ce0-49c0-9f2b-8fd5dcd89b4b']::uuid[] AND bound_at<=statement_timestamp() AND expires_at>statement_timestamp())
 OR NOT EXISTS(SELECT 1 FROM mission_factory_owner.c444_runtime_control WHERE singleton AND enabled AND bound_at<=statement_timestamp() AND expires_at>statement_timestamp())
 OR NOT EXISTS(SELECT 1 FROM mission_factory_owner.c463_optin_control WHERE singleton AND enabled AND p_session=ANY(session_ids) AND m.master_user=ANY(master_user_ids) AND bound_at<=statement_timestamp() AND expires_at>statement_timestamp())
 OR EXISTS(SELECT 1 FROM public.combat_v2_sessions WHERE master_session_id=p_session AND(state IS DISTINCT FROM 'chiuso' OR closed_at IS NULL))
 THEN RAISE EXCEPTION 'HUMAN34_OWN_CLOSED_STAFF_TERMINAL_REQUIRED' USING ERRCODE='42501';END IF;
 receipt:=mission_factory_owner.c444_terminal_confirmed_v1(p_session);
 IF receipt IS NULL OR receipt IS DISTINCT FROM tr.receipt OR receipt->>'schema_version' IS DISTINCT FROM 'quest-episode-terminal/1' OR receipt->>'native_terminal_receipt_id' IS DISTINCT FROM p_receipt::text THEN RAISE EXCEPTION 'HUMAN34_EXACT_CONFIRMED_TERMINAL_REQUIRED' USING ERRCODE='40001';END IF;
 PERFORM 1 FROM public.master_v2_participants WHERE session_id=p_session ORDER BY character_id FOR UPDATE;
 IF (SELECT count(*) FROM public.master_v2_participants WHERE session_id=p_session)<>cardinality(q.roster_character_ids)
 OR EXISTS(SELECT 1 FROM public.master_v2_participants mp LEFT JOIN public.characters c ON c.id=mp.character_id WHERE mp.session_id=p_session AND(NOT(mp.character_id=ANY(q.roster_character_ids)) OR mp.user_id_snapshot IS DISTINCT FROM c.user_id OR mp.engagement_state NOT IN('attivo','sospeso','concluso')))
 THEN RAISE EXCEPTION 'HUMAN34_PARTICIPANT_ROSTER_SNAPSHOT_DRIFT' USING ERRCODE='40001';END IF;
 UPDATE public.master_v2_participants SET engagement_state='concluso',left_at=coalesce(left_at,clock_timestamp()) WHERE session_id=p_session AND(engagement_state<>'concluso' OR left_at IS NULL);
 GET DIAGNOSTICS affected=ROW_COUNT;
 IF EXISTS(SELECT 1 FROM public.master_v2_participants WHERE session_id=p_session AND(engagement_state<>'concluso' OR left_at IS NULL)) THEN RAISE EXCEPTION 'HUMAN34_PARTICIPANTS_FINALIZE_CAS';END IF;
 RETURN jsonb_build_object('schema_version','human-native-participants-finalization/1','session_id',p_session,'terminal_receipt_id',p_receipt,'released_count',affected);
END
$function$

