 OR d.document->>'content_kind' IS DISTINCT FROM 'quest_human' OR d.state NOT IN('draft','previewed','published')
 OR ready.state<>'enabled' OR ready.scope<>'staff' OR mission_factory_owner.human_verified_context_valid_v1(p_context,ready.revision_sha256) IS DISTINCT FROM true
 OR NOT ready.staff_guards_verified OR NOT ready.published_assets_verified
 OR encode(extensions.digest(convert_to(ready.canonical_preimage,'UTF8'),'sha256'),'hex') IS DISTINCT FROM ready.revision_sha256
 OR jsonb_typeof(d.document#>'{quest,episodes}') IS DISTINCT FROM 'array'
 THEN RETURN NULL;END IF;
 n:=jsonb_array_length(d.document#>'{quest,episodes}');IF n<1 THEN RETURN NULL;END IF;
 policy_text:=d.document#>>ARRAY['quest','episodes',(n-1)::text,'terminal_rules','reward_policy_id'];
 SELECT * INTO policy FROM mission_factory_owner.quest_reward_policy_versions WHERE id::text=policy_text AND qualified AND scope='staff';
 SELECT * INTO roster FROM mission_factory_owner.quest_roster_assignments
 WHERE id::text=d.document#>>'{quest,roster_assignment_id}' AND draft_id=d.id AND active;
 IF policy.id IS NULL OR roster.id IS NULL OR mission_factory_owner.sha(policy.document) IS DISTINCT FROM policy.document_sha256
 OR policy.document IS DISTINCT FROM mission_factory_owner.quest_reward_fixed30_document_v2()
 THEN RETURN NULL;END IF;
 IF g.public_staff_draft_id=p_draft THEN
  SELECT * INTO rel FROM mission_public_owner.release_admissions_v1 WHERE release_sha256=CASE WHEN observation->>'schema_version'='human-compatible-release-identity/1' THEN observation->>'observed_revision_sha256' ELSE g.public_staff_release_sha256 END;
  IF NOT g.public_staff_enabled OR mission_factory_owner.c416_kind_live_v1() IS DISTINCT FROM true OR mission_factory_owner.c444_enabled_v1() IS DISTINCT FROM true
  OR g.public_staff_draft_version IS DISTINCT FROM p_version OR g.public_staff_source_sha256 IS DISTINCT FROM p_source
  OR g.public_staff_release_sha256 IS DISTINCT FROM ready.revision_sha256 OR rel.release_sha256 IS NULL
  OR rel.contract_version<>'mission-public-admission/1' OR rel.independent_review_ref IS DISTINCT FROM (CASE WHEN observation->>'schema_version'='human-compatible-release-identity/1' THEN observation->>'observed_independent_review_ref' ELSE ready.independent_review_ref END)
  OR rel.staff_evidence_ref IS DISTINCT FROM 'AUTHORIZED_TEST_MANIFEST:'||g.public_staff_test_manifest_ref
  OR g.allowed_auth_ids IS DISTINCT FROM (SELECT allowed_auth_ids FROM mission_factory_owner.c416_kind_admission WHERE singleton) OR cardinality(g.allowed_auth_ids) IS DISTINCT FROM 2 OR array_position(g.allowed_auth_ids,NULL) IS NOT NULL
  OR NOT(g.allowed_auth_ids @> ARRAY['f0856d53-83a6-4de0-bc0c-12c87916e665'::uuid,'b4952ed5-5ce0-49c0-9f2b-8fd5dcd89b4b'::uuid])
  OR NOT(d.author_user=ANY(g.allowed_auth_ids))
  OR NOT EXISTS(SELECT 1 FROM public.locations WHERE id='0b85f354-9cdb-47e1-baf9-3d266bb7e06b'::uuid AND is_active AND is_test)
  OR EXISTS(SELECT 1 FROM unnest(roster.member_character_ids)x(id) LEFT JOIN public.characters c ON c.id=x.id
   WHERE c.id IS NULL OR NOT(c.user_id=ANY(g.allowed_auth_ids)))
  OR NOT EXISTS(SELECT 1 FROM mission_factory_owner.quest_fixed30_policy_requests qr
   JOIN mission_factory_owner.catalog_versions cv ON cv.version=d.catalog_version AND cv.active AND cv.qualified
   WHERE qr.policy_id=policy.id AND qr.document_sha256=policy.document_sha256
   AND qr.catalog_version=cv.version AND qr.catalog_sha256=cv.document_sha256)
  THEN RETURN NULL;END IF;
  IF observation->>'schema_version'='human-compatible-release-identity/1' THEN
  expected_qual:=mission_factory_owner.sha(jsonb_build_object('schema_version','quest-human-public-staff-compatible-context/1','release_sha256',ready.revision_sha256,'observed_release_sha256',observation->>'observed_revision_sha256','compatibility_sha256',observation->>'compatibility_sha256',
   'db_sha256',rel.db_sha256,'edge_sha256',rel.edge_sha256,'client_sha256',rel.client_sha256,'config_sha256',rel.configuration_sha256,
   'independent_review_ref',rel.independent_review_ref,'authorized_test_manifest_ref',g.public_staff_test_manifest_ref,
   'draft_id',p_draft,'draft_version',p_version,'source_sha256',p_source,'allowed_auth_ids',g.allowed_auth_ids,
   'human_kind_request',(SELECT request_key FROM mission_factory_owner.c416_kind_admission WHERE singleton),'human_kind_review_sha256',(SELECT review_sha256 FROM mission_factory_owner.c416_kind_admission WHERE singleton),'location_id','0b85f354-9cdb-47e1-baf9-3d266bb7e06b'));
  ELSE
  expected_qual:=mission_factory_owner.sha(jsonb_build_object('schema_version','quest-human-public-staff-context/1','release_sha256',rel.release_sha256,
   'db_sha256',rel.db_sha256,'edge_sha256',rel.edge_sha256,'client_sha256',rel.client_sha256,'config_sha256',rel.configuration_sha256,
   'independent_review_ref',rel.independent_review_ref,'authorized_test_manifest_ref',g.public_staff_test_manifest_ref,
   'draft_id',p_draft,'draft_version',p_version,'source_sha256',p_source,'allowed_auth_ids',g.allowed_auth_ids,
   'human_kind_request',(SELECT request_key FROM mission_factory_owner.c416_kind_admission WHERE singleton),'human_kind_review_sha256',(SELECT review_sha256 FROM mission_factory_owner.c416_kind_admission WHERE singleton),'location_id','0b85f354-9cdb-47e1-baf9-3d266bb7e06b'));
  END IF;
  IF g.public_staff_qualification_sha256 IS DISTINCT FROM expected_qual THEN
   IF EXISTS(SELECT 1 FROM mission_factory_owner.quest_arcs hc_existing WHERE hc_existing.draft_id=p_draft AND hc_existing.draft_version=p_version AND hc_existing.source_sha256=p_source AND (mission_factory_owner.human_staff_context_records_v1(observation,observation->>'observed_revision_sha256',hc_existing.id,'legacy_current',g) OR mission_factory_owner.human_staff_lease_valid_with_context_v1(observation,hc_existing.id,true,p_context))) THEN
    expected_qual:=g.public_staff_qualification_sha256;
   ELSE RETURN NULL;END IF;
  END IF;
  RETURN jsonb_build_object('execution_context','staff_simulation','target','staff','revision_sha256',CASE WHEN observation->>'schema_version'='human-compatible-release-identity/1' THEN ready.revision_sha256 ELSE rel.release_sha256 END,
   'qualification_sha256',expected_qual,'allowed_auth_ids',to_jsonb(g.allowed_auth_ids),'location_id','0b85f354-9cdb-47e1-baf9-3d266bb7e06b');
 END IF;
 IF (NOT g.public_enabled AND (mission_public_owner.human_positive_qualification_v1(g.public_release_sha256,true)->>'schema_version' IS NOT DISTINCT FROM 'human-owner-accepted-release/1') IS DISTINCT FROM true) OR g.public_release_sha256 IS DISTINCT FROM ready.revision_sha256
 OR (g.public_policy_id IS DISTINCT FROM policy.id AND NOT(EXISTS(SELECT 1 FROM mission_factory_owner.quest_reward_policy_versions hp_new JOIN mission_factory_owner.quest_reward_policy_versions hp_old ON hp_old.id=g.public_policy_id
 WHERE hp_new.id=policy.id AND hp_new.qualified AND hp_old.qualified AND hp_new.scope='staff' AND hp_old.scope='staff' AND hp_new.document_sha256='34197acc065af70dc89ac15d54c19044f4e5af07c91b5869eb0b360a0fcfef19' AND hp_old.document_sha256=hp_new.document_sha256 AND hp_new.document IS NOT DISTINCT FROM hp_old.document AND hp_new.document IS NOT DISTINCT FROM mission_factory_owner.quest_reward_fixed30_document_v2() AND mission_factory_owner.sha(hp_new.document)=hp_new.document_sha256 AND mission_factory_owner.sha(hp_old.document)=hp_old.document_sha256
 AND EXISTS(SELECT 1 FROM mission_factory_owner.quest_fixed30_policy_requests hp_q JOIN mission_factory_owner.catalog_versions hp_cv ON hp_cv.version=hp_q.catalog_version AND hp_cv.active AND hp_cv.qualified AND hp_cv.document_sha256=hp_q.catalog_sha256 AND hp_cv.document_sha256=mission_factory_owner.sha(hp_cv.document) WHERE hp_q.policy_id=hp_new.id AND hp_q.document_sha256=hp_new.document_sha256 AND hp_q.catalog_version=d.catalog_version)))) OR g.public_qualification_sha256 IS NULL
 OR mission_public_owner.human_positive_qualification_v1(g.public_release_sha256,true) IS NULL THEN RETURN NULL;END IF;
 RETURN jsonb_build_object('execution_context','public_real','target','public','revision_sha256',g.public_release_sha256,
 'qualification_sha256',g.public_qualification_sha256,'allowed_auth_ids','[]'::jsonb,'location_id',NULL);
END $function$

CREATE OR REPLACE FUNCTION mission_factory_owner.human_ordinary_deep_validate_v1(p_draft uuid, p_document jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
<<validator>>
declare errors jsonb:='[]'::jsonb; e jsonb; ph jsonb; t jsonb; m jsonb; a jsonb; b jsonb;
        cap jsonb; cat jsonb; caps jsonb; ref jsonb; phase_keys text[]; actor_keys text[];
        bound_keys text[]:='{}'; media mission_factory_owner.context_media_tickets;
        arena combat_spatial.arena_templates; episode_key text; step_key text; ident uuid;
        d mission_factory_owner.drafts%rowtype; item jsonb;
begin
  if p_draft is null or NOT ((p_document->>'schema_version'='mission-factory-draft/2' AND p_document->>'content_kind'='quest_ai') OR (p_document->>'schema_version'='mission-factory-draft/3' AND p_document->>'content_kind'='quest_human'))
  then raise exception 'MF_QUEST_DEEP_INPUT' using errcode='22023'; end if;
  perform mission_factory_owner.validate_quest_draft_v2(p_document);
  select * into d from mission_factory_owner.drafts where id=p_draft;
  if d.id is null or d.document is distinct from p_document
     or d.document_sha256 is distinct from mission_factory_owner.sha(p_document) then
    raise exception 'MF_NPC_AUTHORING_DRAFT_STALE' using errcode='40001'; end if;
  SELECT cv.document INTO STRICT cat FROM mission_factory_owner.catalog_versions cv WHERE cv.version=d.catalog_version AND cv.active AND cv.qualified AND cv.document_sha256=mission_factory_owner.sha(cv.document);caps:=cat->'capabilities';
 PERFORM mission_factory_owner.human_ordinary_npc_bundle_assert_v1(p_draft);
  for b in select value from jsonb_array_elements(p_document->'npc_bindings') loop
    if b->>'actor_key'=any(bound_keys) then
      errors:=errors||jsonb_build_array(jsonb_build_object('code','MF_QUEST_NPC_DUPLICATE','path','npc_bindings'));
    else bound_keys:=bound_keys||(b->>'actor_key'); end if;
    for a in select value from jsonb_array_elements(b->'phase_keys') loop
      if jsonb_typeof(a) is distinct from 'string' or not exists(
        select 1 from jsonb_array_elements(p_document#>'{quest,episodes}') ep,
                      jsonb_array_elements(ep.value->'phases') pp
        where (ep.value->>'episode_key')||'/'||(pp.value->>'step_key')=a#>>'{}') then
        errors:=errors||jsonb_build_array(jsonb_build_object('code','MF_QUEST_NPC_PHASE_BINDING',
          'path','npc_bindings'));
      end if;
    end loop;
    if coalesce(b->>'npc_id','') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
       or coalesce(b->>'npc_version_id','') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    then errors:=errors||jsonb_build_array(jsonb_build_object('code','MF_QUEST_NPC_ID','path','npc_bindings'));
    else
      begin
        item:=mission_factory_owner.npc_reference((b->>'npc_id')::uuid,(b->>'npc_version_id')::uuid,(b->>'combat')::boolean);
        ref:=mission_factory_owner.npc_reference((b->>'npc_id')::uuid,(b->>'npc_version_id')::uuid,(b->>'combat')::boolean);
        if ref->>'bundle_sha256' is null
           or item->>'bundle_sha256' is distinct from ref->>'bundle_sha256' then
          errors:=errors||jsonb_build_array(jsonb_build_object('code','MF_QUEST_NPC_STALE','path','npc_bindings'));
        end if;
      exception when SQLSTATE '55000' then
        errors:=errors||jsonb_build_array(jsonb_build_object('code','MF_QUEST_NPC_UNQUALIFIED','path','npc_bindings'));
      end;
    end if;
  end loop;
  for e in select value from jsonb_array_elements(p_document#>'{quest,episodes}') loop
    episode_key:=e->>'episode_key'; phase_keys:='{}'; actor_keys:='{}';
    for ph in select value from jsonb_array_elements(e->'phases') loop
      step_key:=ph->>'step_key'; phase_keys:=phase_keys||step_key;
      perform mission_factory_owner.c360_native_phase_assert_v1(ph);
      select value into cap from jsonb_array_elements(coalesce(caps,'[]'::jsonb)) x
        where x.value->>'key'=ph->>'capability_key' and x.value->>'qualified'='true' AND p_document->>'content_kind'='quest_human' AND x.value->>'key' IN('narrative.scene','combat.encounter','d100.native','terminal.result') limit 1;
      if cap is null then
        errors:=errors||jsonb_build_array(jsonb_build_object('code','MF_QUEST_CAPABILITY_UNQUALIFIED',
          'path','quest.episodes.'||episode_key||'.phases.'||step_key));
      else
        for t in select value from jsonb_array_elements(ph->'transition_options') loop
          if not (coalesce(cap->'decision_keys','[]'::jsonb) ? (t->>'decision_key')) then
            errors:=errors||jsonb_build_array(jsonb_build_object('code','MF_QUEST_DECISION_UNQUALIFIED',
              'path','quest.episodes.'||episode_key||'.phases.'||step_key));
          end if;
        end loop;
      end if;
    end loop;
    for ph in select value from jsonb_array_elements(e->'phases') loop
      for t in select value from jsonb_array_elements(ph->'transition_options') loop
        if t->>'to_step_key' is not null and not (t->>'to_step_key'=any(phase_keys)) then
          errors:=errors||jsonb_build_array(jsonb_build_object('code','MF_QUEST_TRANSITION_TARGET',
            'path','quest.episodes.'||episode_key||'.phases.'||(ph->>'step_key')));
        end if;
      end loop;
    end loop;
    if not (e#>>'{terminal_rules,terminal_step_key}'=any(phase_keys)) then
      errors:=errors||jsonb_build_array(jsonb_build_object('code','MF_QUEST_TERMINAL_STEP',
        'path','quest.episodes.'||episode_key||'.terminal_rules'));
    end if;
    if not exists(select 1 from jsonb_array_elements(coalesce(caps,'[]'::jsonb)) x
      where x.value->>'key'=e#>>'{terminal_rules,outcome_capability_key}'
        and x.value->>'family'='terminal' and x.value->>'qualified'='true') then
      errors:=errors||jsonb_build_array(jsonb_build_object('code','MF_QUEST_TERMINAL_CAPABILITY',
        'path','quest.episodes.'||episode_key||'.terminal_rules'));
    end if;
    for a in select value from jsonb_array_elements(e->'npc_actor_keys') loop
      if jsonb_typeof(a) is distinct from 'string' or not (a#>>'{}'=any(bound_keys))
         or a#>>'{}'=any(actor_keys) then
        errors:=errors||jsonb_build_array(jsonb_build_object('code','MF_QUEST_EPISODE_NPC_BINDING',
          'path','quest.episodes.'||episode_key||'.npc_actor_keys'));
      else actor_keys:=actor_keys||(a#>>'{}'); end if;
    end loop;
    for m in select value from jsonb_array_elements(e->'maps') loop
      step_key:=m->>'step_key';
      if m->>'context_media_id' is not null then
        if coalesce(m->>'context_media_id','') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
          errors:=errors||jsonb_build_array(jsonb_build_object('code','MF_QUEST_MEDIA_ID',
            'path','quest.episodes.'||episode_key||'.maps.'||step_key));
        else
          select * into media from mission_factory_owner.context_media_tickets
            where media_id=(m->>'context_media_id')::uuid and draft_id=p_draft
              and content_kind=p_document->>'content_kind' and episode_key=validator.episode_key
              and step_key=validator.step_key and active;
          if media.media_id is null or media.registered_at is null
             or media.result->>'schema_version' is distinct from 'mission-factory-context-media-registration/2'
             or media.result->>'sha256' is distinct from media.sha256
             or not exists(select 1 from storage.objects o
                 where o.bucket_id='location-images' and o.name=media.object_path) then
            errors:=errors||jsonb_build_array(jsonb_build_object('code','MF_QUEST_MEDIA_STALE',
              'path','quest.episodes.'||episode_key||'.maps.'||step_key));
          end if;
        end if;
      end if;
      if jsonb_typeof(m->'arena_ref')='object' then
        ref:=m->'arena_ref';
        if coalesce(ref->>'template_version','') !~ '^[1-9][0-9]{0,8}$' then
          errors:=errors||jsonb_build_array(jsonb_build_object('code','MF_QUEST_ARENA_VERSION',
            'path','quest.episodes.'||episode_key||'.maps.'||step_key));
        else
          select * into arena from combat_spatial.arena_templates
            where template_key=ref->>'template_key'
              and template_version=(ref->>'template_version')::integer;
          if arena.template_key is null then
            errors:=errors||jsonb_build_array(jsonb_build_object('code','MF_QUEST_ARENA_UNQUALIFIED',
              'path','quest.episodes.'||episode_key||'.maps.'||step_key));
          elsif arena.status<>'ready'
             or combat_spatial.template_errors(arena.template_key,arena.template_version)<>'[]'::jsonb
             or arena.geometry_hash is distinct from
                combat_spatial.geometry_fingerprint(arena.template_key,arena.template_version) then
            errors:=errors||jsonb_build_array(jsonb_build_object('code','MF_QUEST_ARENA_UNQUALIFIED',
              'path','quest.episodes.'||episode_key||'.maps.'||step_key));
          end if;
        end if;
      end if;
    end loop;
  end loop;
  return errors;
end $function$

CREATE OR REPLACE FUNCTION mission_factory_owner.human_ordinary_enrollment_open_v1(p_episode uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare ep mission_factory_owner.quest_episodes; a mission_factory_owner.quest_arcs;
begin


 select * into ep from mission_factory_owner.quest_episodes where id=p_episode;
 select * into a from mission_factory_owner.quest_arcs where id=ep.arc_id;
 if ep.id is null or ep.state<>'source_only' or exists(select 1 from mission_factory_owner.quest_run_sources where episode_id=p_episode) then return false;end if;
 if not mission_factory_owner.quest_public_open_v3(a.id) then return false;end if;
 IF mission_factory_owner.human_ordinary_arc_scope_v1(a.id,true) IS DISTINCT FROM true THEN RETURN false;END IF;
 if ep.ordinal=1 then return a.state in('staff_source','public_source');end if;
 return a.quest_kind='trama' and a.state='in_progress' and exists(
   select 1 from mission_factory_owner.quest_episodes prev
   join mission_factory_owner.quest_run_sources q on q.episode_id=prev.id and q.state='terminal'
   join mission_factory_owner.quest_terminal_receipts tr on tr.id=q.terminal_receipt_id
   where prev.arc_id=a.id and prev.ordinal=ep.ordinal-1
     and mission_factory_owner.quest_terminal_confirmed_v1(q.session_id) is not null);
end $function$

CREATE OR REPLACE FUNCTION mission_factory_owner.human_ordinary_execution_read_assert_v1(p_arc uuid, p_active boolean)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE command_context jsonb;
BEGIN
 IF p_active IS DISTINCT FROM true THEN

declare a mission_factory_owner.quest_arcs;g mission_factory_owner.quest_fixed30_admission;rel mission_public_owner.release_admissions_v1;proof jsonb;
begin
 select * into strict a from mission_factory_owner.quest_arcs where id=p_arc;
 IF a.availability_scope IS DISTINCT FROM 'public' OR a.source_document->>'content_kind' IS DISTINCT FROM 'quest_human' THEN RAISE EXCEPTION 'HUMAN_ORDINARY_EXECUTION_KIND_REQUIRED' USING ERRCODE='42501';END IF;
 if p_active then
  proof:=mission_factory_owner.human_ordinary_authority_v1(a.draft_id,a.draft_version,a.source_sha256);
  if proof is null or proof->>'execution_context' is distinct from a.execution_context or proof->>'revision_sha256' is distinct from a.public_release_sha256
  or(a.execution_context='staff_simulation' and (proof->>'qualification_sha256' is distinct from a.execution_qualification_sha256 or proof->'allowed_auth_ids' is distinct from to_jsonb(a.execution_auth_ids)))
  then raise exception 'MF_QUEST_EXECUTION_AUTHORITY_DRIFT' using errcode='55000';end if;
 end if;
 if a.execution_context='public_real' then perform mission_factory_owner.human_ordinary_release_read_assert_v1(a.public_release_sha256,a.reward_policy_id,p_active);return;end if;
 if a.execution_qualification_sha256 is null or cardinality(a.execution_auth_ids)<>2 or array_position(a.execution_auth_ids,null) is not null
 or(select count(distinct x) from unnest(a.execution_auth_ids)x)<>2
 or a.source_sha256<>mission_factory_owner.sha(a.source_document)
 then raise exception 'MF_QUEST_STAFF_CONTEXT_SOURCE_DRIFT' using errcode='40001';end if;
 select * into strict rel from mission_public_owner.release_admissions_v1 where release_sha256=a.public_release_sha256;
 if rel.contract_version<>'mission-public-admission/1' or nullif(btrim(rel.independent_review_ref),'') is null
 then raise exception 'MF_QUEST_STAFF_CONTEXT_RELEASE_UNQUALIFIED' using errcode='55000';end if;
 if p_active then
  select * into strict g from mission_factory_owner.quest_fixed30_admission where singleton;
  if not g.public_staff_enabled or mission_factory_owner.c416_kind_live_v1() IS DISTINCT FROM true or mission_factory_owner.c444_enabled_v1() IS DISTINCT FROM true
  or g.public_staff_qualification_sha256 is distinct from a.execution_qualification_sha256
  or g.public_staff_release_sha256 is distinct from a.public_release_sha256 or g.allowed_auth_ids is distinct from a.execution_auth_ids
  or g.public_staff_draft_id<>a.draft_id or g.public_staff_draft_version<>a.draft_version or g.public_staff_source_sha256<>a.source_sha256
  then raise exception 'MF_QUEST_STAFF_CONTEXT_UNQUALIFIED' using errcode='55000';end if;
 end if;
 if exists(select 1 from unnest(a.member_character_ids)x(id) left join public.characters c on c.id=x.id
 where c.id is null or not(c.user_id=any(a.execution_auth_ids)))
 then raise exception 'MF_QUEST_STAFF_CONTEXT_ACTOR_SCOPE' using errcode='42501';end if;
end;
 RETURN;
 END IF;
 command_context:=mission_factory_owner.human_verified_context_v1('5ab4234b32294cc26472855447e6230f62c5e07308768816ae0c2ea304d94366');
 PERFORM mission_factory_owner.human_ordinary_execution_read_assert_with_context_v1(p_arc,p_active,command_context);RETURN;
END;
$function$

CREATE OR REPLACE FUNCTION mission_factory_owner.human_ordinary_execution_read_assert_with_context_v1(p_arc uuid, p_active boolean, p_context jsonb)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare a mission_factory_owner.quest_arcs;g mission_factory_owner.quest_fixed30_admission;rel mission_public_owner.release_admissions_v1;proof jsonb;
begin
 IF mission_factory_owner.human_verified_context_valid_v1(p_context,'5ab4234b32294cc26472855447e6230f62c5e07308768816ae0c2ea304d94366') IS DISTINCT FROM true THEN RAISE EXCEPTION 'HUMAN_SERVER_COMMAND_CONTEXT_INVALID' USING ERRCODE='42501';END IF;

 select * into strict a from mission_factory_owner.quest_arcs where id=p_arc;
 IF a.availability_scope IS DISTINCT FROM 'public' OR a.source_document->>'content_kind' IS DISTINCT FROM 'quest_human' THEN RAISE EXCEPTION 'HUMAN_ORDINARY_EXECUTION_KIND_REQUIRED' USING ERRCODE='42501';END IF;
 if p_active then
  proof:=mission_factory_owner.human_ordinary_authority_with_context_v1(a.draft_id,a.draft_version,a.source_sha256,p_context);
  if proof is null or proof->>'execution_context' is distinct from a.execution_context or proof->>'revision_sha256' is distinct from a.public_release_sha256
  or(a.execution_context='staff_simulation' and (proof->>'qualification_sha256' is distinct from a.execution_qualification_sha256 or proof->'allowed_auth_ids' is distinct from to_jsonb(a.execution_auth_ids)))
  then raise exception 'MF_QUEST_EXECUTION_AUTHORITY_DRIFT' using errcode='55000';end if;
 end if;
 if a.execution_context='public_real' then perform mission_factory_owner.human_ordinary_release_read_assert_v1(a.public_release_sha256,a.reward_policy_id,p_active);return;end if;
 if a.execution_qualification_sha256 is null or cardinality(a.execution_auth_ids)<>2 or array_position(a.execution_auth_ids,null) is not null
 or(select count(distinct x) from unnest(a.execution_auth_ids)x)<>2
 or a.source_sha256<>mission_factory_owner.sha(a.source_document)
 then raise exception 'MF_QUEST_STAFF_CONTEXT_SOURCE_DRIFT' using errcode='40001';end if;
 select * into strict rel from mission_public_owner.release_admissions_v1 where release_sha256=a.public_release_sha256;
 if rel.contract_version<>'mission-public-admission/1' or nullif(btrim(rel.independent_review_ref),'') is null
 then raise exception 'MF_QUEST_STAFF_CONTEXT_RELEASE_UNQUALIFIED' using errcode='55000';end if;
 if p_active then
  select * into strict g from mission_factory_owner.quest_fixed30_admission where singleton;
  if not g.public_staff_enabled or mission_factory_owner.c416_kind_live_v1() IS DISTINCT FROM true or mission_factory_owner.c444_enabled_v1() IS DISTINCT FROM true
  or g.public_staff_qualification_sha256 is distinct from a.execution_qualification_sha256
  or g.public_staff_release_sha256 is distinct from a.public_release_sha256 or g.allowed_auth_ids is distinct from a.execution_auth_ids
  or g.public_staff_draft_id<>a.draft_id or g.public_staff_draft_version<>a.draft_version or g.public_staff_source_sha256<>a.source_sha256
  then raise exception 'MF_QUEST_STAFF_CONTEXT_UNQUALIFIED' using errcode='55000';end if;
 end if;
 if exists(select 1 from unnest(a.member_character_ids)x(id) left join public.characters c on c.id=x.id
 where c.id is null or not(c.user_id=any(a.execution_auth_ids)))
 then raise exception 'MF_QUEST_STAFF_CONTEXT_ACTOR_SCOPE' using errcode='42501';end if;
end $function$

CREATE OR REPLACE FUNCTION mission_factory_owner.human_ordinary_final_terminal_v1(p_arc uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE a mission_factory_owner.quest_arcs;q mission_factory_owner.quest_run_sources;t mission_factory_owner.quest_terminal_receipts;
BEGIN
 IF auth.uid() IS NULL OR auth.role() IS DISTINCT FROM 'authenticated' OR public.master_v2_is_master(auth.uid()) IS DISTINCT FROM true OR p_arc IS NULL THEN RETURN NULL;END IF;
 SELECT * INTO a FROM mission_factory_owner.quest_arcs WHERE id=p_arc;
 IF a.id IS NULL OR a.created_by IS DISTINCT FROM auth.uid() OR a.state NOT IN('completed','failed') OR a.availability_scope IS DISTINCT FROM 'public' OR a.source_document->>'content_kind' IS DISTINCT FROM 'quest_human' OR a.source_sha256 IS DISTINCT FROM mission_factory_owner.sha(a.source_document) THEN RETURN NULL;END IF;
 SELECT * INTO q FROM mission_factory_owner.quest_run_sources WHERE arc_id=p_arc AND (start_event_id IS NOT NULL OR started_at IS NOT NULL) ORDER BY episode_ordinal DESC LIMIT 1;
 IF q.session_id IS NULL OR q.state IS DISTINCT FROM 'terminal' OR q.terminal_receipt_id IS NULL OR q.started_at IS NULL OR q.terminal_at IS NULL OR q.start_event_id IS NULL OR q.opening_publication_id IS NULL OR q.availability_scope IS DISTINCT FROM a.availability_scope OR q.public_release_sha256 IS DISTINCT FROM a.public_release_sha256 OR q.execution_context IS DISTINCT FROM a.execution_context THEN RETURN NULL;END IF;
 SELECT * INTO t FROM mission_factory_owner.quest_terminal_receipts WHERE id=q.terminal_receipt_id AND session_id=q.session_id AND episode_id=q.episode_id AND source_sha256=q.source_sha256;
 IF t.id IS NULL OR t.receipt->>'native_terminal_receipt_id' IS DISTINCT FROM t.id::text OR mission_factory_owner.c444_terminal_confirmed_v1(q.session_id) IS DISTINCT FROM t.receipt OR t.outcome IS DISTINCT FROM (CASE WHEN a.state='completed' THEN 'success' ELSE 'failure' END) OR (a.state='completed' AND EXISTS(SELECT 1 FROM mission_factory_owner.quest_episodes later_episode WHERE later_episode.arc_id=a.id AND later_episode.ordinal>q.episode_ordinal)) THEN RETURN NULL;END IF;
 RETURN t.id;
END $function$

CREATE OR REPLACE FUNCTION mission_factory_owner.human_ordinary_npc_bundle_assert_v1(p_draft uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE d mission_factory_owner.drafts;a jsonb;b png_builder_internal.bundles;pair jsonb;ref jsonb;
BEGIN
 SELECT * INTO STRICT d FROM mission_factory_owner.drafts WHERE id=p_draft;
 IF auth.uid() IS NULL OR auth.role() IS DISTINCT FROM 'authenticated' OR d.author_user IS DISTINCT FROM auth.uid()
 OR d.document->>'content_kind' IS DISTINCT FROM 'quest_human' OR d.document_sha256 IS DISTINCT FROM mission_factory_owner.sha(d.document)
 THEN RAISE EXCEPTION 'HUMAN_ORDINARY_NPC_DRAFT_AUTHORITY' USING ERRCODE='42501';END IF;
 PERFORM mission_factory_owner.validate_quest_draft_v2(d.document);
 FOR a IN SELECT value FROM jsonb_array_elements(d.document->'npc_bindings') LOOP
 SELECT * INTO STRICT b FROM png_builder_internal.bundles WHERE id=(a->>'npc_version_id')::uuid AND template_id=(a->>'npc_id')::uuid;
 ref:=mission_factory_owner.npc_reference(b.template_id,b.id,(a->>'combat')::boolean);
 IF b.bundle_kind='narrative' THEN
 pair:=png_builder_internal.npc_media_pair_resolve_v1(b.template_id,b.narrative_version_id);
 IF b.media_ids IS DISTINCT FROM ARRAY[(pair->>'portrait_media_id')::uuid,(pair->>'marker_media_id')::uuid] THEN RAISE EXCEPTION 'HUMAN_ORDINARY_NARRATIVE_MEDIA_STALE' USING ERRCODE='55000';END IF;
 CONTINUE;END IF;
 IF EXISTS(SELECT 1 FROM public.nb_mechanical_versions cm WHERE cm.id=b.mechanical_version_id AND cm.profile_kind='npc_custom') THEN
  IF mission_factory_owner.human_custom_ordinary_capability_v1(p_draft,false) IS NULL THEN RAISE EXCEPTION 'HUMAN_CUSTOM_CAPABILITY_NOT_QUALIFIED' USING ERRCODE='55000';END IF;
  PERFORM png_builder_internal.npc_custom_combat_attest_assert_v1(b.template_id,b.narrative_version_id,b.id);
  IF b.ownership_mode IS DISTINCT FROM 'adopted' OR b.owns_upstream IS DISTINCT FROM false OR b.certified_payload->'document' IS DISTINCT FROM (png_builder_internal.npc_custom_combat_source_v1(b.template_id,b.narrative_version_id)->'document') THEN RAISE EXCEPTION 'HUMAN_CUSTOM_CANONICAL_BUNDLE_DRIFT' USING ERRCODE='55000';END IF;
  CONTINUE;
 END IF;
 pair:=mission_factory_owner.human_existing_legacy_media_pair_v1(b.template_id,b.narrative_version_id);
 IF b.certified_payload->>'schema_version' IS DISTINCT FROM 'png-builder-certified-payload/1.0'
 OR b.ownership_mode IS DISTINCT FROM 'adopted' OR b.owns_upstream IS DISTINCT FROM false
 OR NOT EXISTS(SELECT 1 FROM public.nb_templates t WHERE t.id=b.template_id AND t.current_version_id=b.narrative_version_id AND t.lifecycle_state='approved' AND t.deactivated_at IS NULL)
 OR b.certified_payload#>'{document,media_ids}' IS DISTINCT FROM to_jsonb(b.media_ids)
 OR NOT(to_jsonb(b.media_ids) ? (pair->>'portrait_media_id')) OR to_jsonb(b.media_ids) IS DISTINCT FROM (SELECT coalesce(jsonb_agg(to_jsonb(cm.id) ORDER BY cm.media_version_no,cm.id),'[]'::jsonb) FROM public.nb_template_media_versions cm WHERE cm.template_id=b.template_id AND cm.template_version_id=b.narrative_version_id AND cm.lifecycle_state='approved' AND cm.active AND cm.sha256=cm.verified_sha256)
 OR (a->>'combat'='true' AND NOT EXISTS(SELECT 1 FROM public.nb_mechanical_versions v WHERE v.id=b.mechanical_version_id AND v.profile_kind='legacy' AND v.review_state='approved'))
 THEN RAISE EXCEPTION 'HUMAN_ORDINARY_CANONICAL_BUNDLE_REQUIRED' USING ERRCODE='55000';END IF;
 END LOOP;
END $function$

CREATE OR REPLACE FUNCTION mission_factory_owner.human_ordinary_participants_finish_v1(p_session uuid, p_receipt uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE m public.master_v2_sessions;q mission_factory_owner.quest_run_sources;tr mission_factory_owner.quest_terminal_receipts;verified jsonb;affected integer;locked_location uuid;
BEGIN
 IF auth.uid() IS NULL OR auth.role() IS DISTINCT FROM 'authenticated' OR public.is_staff() IS DISTINCT FROM true
 OR p_session IS NULL OR p_receipt IS NULL OR mission_factory_owner.human_ordinary_source_v1(p_session,true) IS NULL
 THEN RAISE EXCEPTION 'HUMAN_ORDINARY_FINISH_NORMAL_MASTER_REQUIRED' USING ERRCODE='42501';END IF;
 SELECT location_id INTO STRICT locked_location FROM mission_factory_owner.quest_run_sources WHERE session_id=p_session;
 PERFORM 1 FROM public.locations WHERE id=locked_location FOR UPDATE;
 PERFORM public.master_v2_lock_scope(p_session);
 SELECT * INTO STRICT m FROM public.master_v2_sessions WHERE id=p_session FOR UPDATE;
 SELECT * INTO STRICT q FROM mission_factory_owner.quest_run_sources WHERE session_id=p_session FOR SHARE;
 SELECT * INTO STRICT tr FROM mission_factory_owner.quest_terminal_receipts WHERE id=p_receipt AND session_id=p_session FOR SHARE;
 verified:=mission_factory_owner.c444_terminal_confirmed_v1(p_session);
 IF m.master_user IS DISTINCT FROM auth.uid() OR m.stato IS DISTINCT FROM 'chiusa' OR m.closed_at IS NULL OR m.suspended_at IS NOT NULL
 OR m.location_id IS DISTINCT FROM locked_location OR q.location_id IS DISTINCT FROM locked_location
 OR q.state IS DISTINCT FROM 'terminal' OR q.terminal_receipt_id IS DISTINCT FROM p_receipt OR verified IS NULL OR verified IS DISTINCT FROM tr.receipt
 OR tr.episode_id IS DISTINCT FROM q.episode_id OR tr.source_sha256 IS DISTINCT FROM q.source_sha256
 OR cardinality(q.roster_character_ids) NOT BETWEEN 1 AND 4 OR q.roster_snapshot_sha256 IS DISTINCT FROM mission_factory_owner.sha(to_jsonb(q.roster_character_ids))
 OR EXISTS(SELECT 1 FROM public.combat_v2_sessions WHERE master_session_id=p_session AND(state IS DISTINCT FROM 'chiuso' OR closed_at IS NULL))
 THEN RAISE EXCEPTION 'HUMAN_ORDINARY_EXACT_CLOSED_TERMINAL_REQUIRED' USING ERRCODE='42501';END IF;
 PERFORM 1 FROM public.master_v2_participants WHERE session_id=p_session ORDER BY character_id FOR UPDATE;
 IF (SELECT count(*) FROM public.master_v2_participants WHERE session_id=p_session)<>cardinality(q.roster_character_ids)
 OR EXISTS(SELECT 1 FROM public.master_v2_participants mp LEFT JOIN public.characters ch ON ch.id=mp.character_id WHERE mp.session_id=p_session
 AND(NOT(mp.character_id=ANY(q.roster_character_ids)) OR mp.user_id_snapshot IS DISTINCT FROM ch.user_id OR mp.joined_at>q.started_at
 OR mp.engagement_state NOT IN('attivo','sospeso','concluso') OR (mp.left_at IS NOT NULL AND (mp.engagement_state<>'concluso' OR mp.left_at<m.closed_at))))
 THEN RAISE EXCEPTION 'HUMAN_ORDINARY_PARTICIPATION_BEFORE_TERMINAL_UNPROVEN' USING ERRCODE='40001';END IF;
 UPDATE public.master_v2_participants SET engagement_state='concluso',left_at=coalesce(left_at,clock_timestamp()) WHERE session_id=p_session AND(engagement_state<>'concluso' OR left_at IS NULL);
 GET DIAGNOSTICS affected=ROW_COUNT;
 IF EXISTS(SELECT 1 FROM public.master_v2_participants WHERE session_id=p_session AND(engagement_state<>'concluso' OR left_at IS NULL OR left_at<m.closed_at)) THEN RAISE EXCEPTION 'HUMAN_ORDINARY_PARTICIPANTS_FINALIZE_CAS';END IF;
 RETURN jsonb_build_object('schema_version','human-native-participants-finalization/1','session_id',p_session,'terminal_receipt_id',p_receipt,'released_count',affected);
END $function$

CREATE OR REPLACE FUNCTION mission_factory_owner.human_ordinary_peaceful_boundary_v1(p_session uuid, p_encounter uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE m public.master_v2_sessions;q mission_factory_owner.quest_run_sources;r public.mission_run_state;he mission_creation_owner.human_encounters;rr public.combat_v2_rounds;rep public.combat_v2_round_reports;w mission_generic_owner.regia_human_windows_v1;abandoned uuid;ph jsonb;opt jsonb;d mission_generic_owner.definitions;
BEGIN
 IF NOT mission_factory_owner.c395_human_mode_v1(p_session) THEN RETURN NULL;END IF;
 PERFORM mission_factory_owner.c407_identity_v1(p_session);PERFORM mission_factory_owner.c444_source_read_assert_v1(p_session);
 SELECT * INTO STRICT m FROM public.master_v2_sessions WHERE id=p_session;
 SELECT * INTO STRICT q FROM mission_factory_owner.quest_run_sources WHERE session_id=p_session;
 SELECT * INTO STRICT r FROM public.mission_run_state WHERE master_session_id=p_session;
 IF auth.uid() IS DISTINCT FROM m.master_user OR public.is_staff() IS DISTINCT FROM true OR NOT public.master_v2_is_master(auth.uid())
 OR m.owner_kind<>'human' OR m.tipo<>'quest' OR m.mission_id IS NOT NULL OR m.stato<>'in_corso' OR m.closed_at IS NOT NULL OR m.suspended_at IS NOT NULL
 OR mission_factory_owner.human_ordinary_source_v1(p_session,true) IS NULL OR q.state<>'started' OR r.source_kind<>'quest' OR r.run_phase<>'in_corso'
 OR NOT EXISTS(SELECT 1 FROM mission_generic_owner.regia_human_session_optins_v1 o WHERE o.master_session_id=p_session AND o.actor_user=m.master_user)
 OR EXISTS(SELECT 1 FROM public.mission_run_outbox WHERE master_session_id=p_session AND state IN('pending','human_directed'))
 THEN RETURN NULL;END IF;
 SELECT * INTO he FROM mission_creation_owner.human_encounters WHERE master_session_id=p_session AND encounter_id=p_encounter AND step_key=r.current_step_key AND run_control_version=r.control_version;
 IF NOT FOUND OR NOT EXISTS(SELECT 1 FROM public.combat_v2_sessions WHERE id=p_encounter AND master_session_id=p_session AND state='in_corso' AND closed_at IS NULL)
 OR combat_panel_private.uses_simulated_pools(p_encounter) IS DISTINCT FROM (q.execution_context='staff_simulation') OR (q.execution_context='staff_simulation' AND public.combat_v2_values_written(p_encounter) IS DISTINCT FROM false) OR (q.execution_context='public_real' AND public.combat_v2_values_written(p_encounter) IS DISTINCT FROM (SELECT cs.lesiva FROM public.combat_v2_sessions cs WHERE cs.id=p_encounter))
 OR EXISTS(SELECT 1 FROM public.combat_v2_resource_ledger WHERE session_id=p_encounter AND is_simulated IS DISTINCT FROM (q.execution_context='staff_simulation')) THEN RETURN NULL;END IF;
 SELECT * INTO STRICT d FROM mission_generic_owner.definitions WHERE id=q.definition_id;
 SELECT value INTO ph FROM mission_factory_owner.quest_episodes e,LATERAL jsonb_array_elements(e.source_document->'phases')x WHERE e.id=q.episode_id AND value->>'step_key'=r.current_step_key;
 IF ph->>'capability_key' IS DISTINCT FROM 'combat.encounter' THEN RETURN NULL;END IF;
 SELECT value INTO opt FROM jsonb_array_elements(ph->'transition_options')x WHERE value->>'decision_key'='combat.peaceful';
 IF opt IS NULL OR opt->'to_step_key'='null'::jsonb OR NOT EXISTS(SELECT 1 FROM mission_factory_owner.quest_decision_registry WHERE catalog_version=d.definition->>'catalog_version' AND catalog_sha256=d.definition->>'catalog_sha256' AND capability_key='combat.encounter' AND decision_key='combat.peaceful' AND qualified AND trigger_source_kind='combat_terminal' AND native_combat_outcome='peaceful') THEN RETURN NULL;END IF;
 SELECT * INTO rr FROM public.combat_v2_rounds WHERE session_id=p_encounter ORDER BY round_no DESC LIMIT 1;
 IF NOT FOUND THEN RETURN NULL;END IF;
 IF rr.state='raccolta_azioni' AND rr.phase='raccolta_azioni' AND rr.report_id IS NULL AND rr.freeze_at IS NULL AND rr.resolved_at IS NULL AND rr.narrated_at IS NULL THEN
 abandoned:=rr.id;
 IF EXISTS(SELECT 1 FROM public.combat_v2_declarations WHERE round_id=rr.id) OR EXISTS(SELECT 1 FROM public.combat_v2_round_reports WHERE round_id=rr.id)
 OR EXISTS(SELECT 1 FROM public.combat_v2_resource_ledger WHERE round_id=rr.id) OR EXISTS(SELECT 1 FROM public.combat_v2_ratings WHERE round_id=rr.id)
 OR EXISTS(SELECT 1 FROM public.combat_v2_attack_targets WHERE round_id=rr.id) OR EXISTS(SELECT 1 FROM public.combat_v2_defense_coverages WHERE round_id=rr.id)
 OR EXISTS(SELECT 1 FROM public.combat_v2_narratives WHERE round_id=rr.id) OR EXISTS(SELECT 1 FROM public.combat_v2_ai_narrative_previews WHERE round_id=rr.id)
 OR EXISTS(SELECT 1 FROM combat_panel_private.actor_turns WHERE round_id=rr.id AND (main_declaration_id IS NOT NULL OR state<>'ready')) THEN RETURN NULL;END IF;
 SELECT * INTO rr FROM public.combat_v2_rounds WHERE session_id=p_encounter AND id<>abandoned ORDER BY round_no DESC LIMIT 1;
 END IF;
 IF rr.id IS NULL OR rr.state<>'narrato' OR rr.report_id IS NULL OR EXISTS(SELECT 1 FROM public.combat_v2_rounds other WHERE other.session_id=p_encounter AND other.state<>'narrato' AND (abandoned IS NULL OR other.id<>abandoned)) THEN RETURN NULL;END IF;
 SELECT * INTO rep FROM public.combat_v2_round_reports WHERE id=rr.report_id AND round_id=rr.id AND narration_state='pubblicata' AND message_id IS NOT NULL AND values_written=public.combat_v2_values_written(p_encounter);
 IF NOT FOUND THEN RETURN NULL;END IF;
 SELECT * INTO w FROM mission_generic_owner.regia_human_windows_v1 WHERE master_session_id=p_session AND encounter_id=p_encounter AND source_round_id=rr.id AND source_report_id=rep.id AND source_report_sha256=rep.mechanics_sha256 AND state='published' AND message_id=rep.message_id AND publication_id=rep.message_id;
 IF NOT FOUND OR NOT EXISTS(SELECT 1 FROM public.messages msg WHERE msg.id=w.message_id AND msg.location_id=m.location_id AND msg.kind='fato' AND public.combat_v2_sha256(jsonb_build_object('body',msg.body))=w.publication_body_sha256) THEN RETURN NULL;END IF;
 RETURN jsonb_build_object('encounter_id',p_encounter,'run_version',r.control_version,'step_key',r.current_step_key,'source_sha256',q.source_sha256,'narrated_round_id',rr.id,'report_id',rep.id,'report_sha256',rep.mechanics_sha256,'fato_message_id',w.message_id,'fato_sha256',w.publication_body_sha256,'abandoned_round_id',abandoned,'decision_key','combat.peaceful','to_step_key',opt->>'to_step_key');
END
$function$

CREATE OR REPLACE FUNCTION mission_factory_owner.human_ordinary_peaceful_history_complete_v1(p_session uuid, p_encounter uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE proof mission_factory_owner.c444_peaceful_native_receipts_v1;q mission_factory_owner.quest_run_sources;r public.mission_run_state;m public.master_v2_sessions;ev public.combat_v2_events;he mission_creation_owner.human_encounters;ph jsonb;
BEGIN
 IF NOT mission_factory_owner.c395_human_mode_v1(p_session) THEN RETURN false;END IF;
 PERFORM mission_factory_owner.c407_identity_v1(p_session);PERFORM mission_factory_owner.c444_source_read_assert_v1(p_session);
 SELECT * INTO proof FROM mission_factory_owner.c444_peaceful_native_receipts_v1 WHERE session_id=p_session AND encounter_id=p_encounter;
 IF NOT FOUND THEN RETURN false;END IF;
 SELECT * INTO STRICT q FROM mission_factory_owner.quest_run_sources WHERE session_id=p_session;
 SELECT * INTO STRICT r FROM public.mission_run_state WHERE master_session_id=p_session;
 SELECT * INTO STRICT m FROM public.master_v2_sessions WHERE id=p_session;
 SELECT * INTO ev FROM public.combat_v2_events WHERE id=proof.event_id;
 SELECT * INTO he FROM mission_creation_owner.human_encounters WHERE master_session_id=p_session AND encounter_id=p_encounter;
 IF NOT FOUND THEN RETURN false;END IF;
 SELECT value INTO ph FROM mission_factory_owner.quest_episodes e,LATERAL jsonb_array_elements(e.source_document->'phases') x WHERE e.id=q.episode_id AND value->>'step_key'=r.current_step_key;
 IF auth.uid() IS DISTINCT FROM m.master_user OR public.is_staff() IS DISTINCT FROM true OR NOT public.master_v2_is_master(auth.uid())
 OR m.owner_kind<>'human' OR m.tipo<>'quest' OR m.mission_id IS NOT NULL OR m.stato<>'in_corso' OR m.closed_at IS NOT NULL OR m.suspended_at IS NOT NULL
 OR q.state<>'started' OR r.source_kind<>'quest' OR r.run_phase<>'in_corso'
 OR ph->>'capability_key' IS DISTINCT FROM 'terminal.result' OR r.control_version IS DISTINCT FROM proof.run_version+1 OR r.current_step_key IS NOT DISTINCT FROM proof.step_key
 OR NOT EXISTS(SELECT 1 FROM public.mission_run_events te WHERE te.id=r.last_event_id AND te.master_session_id=p_session AND te.operation_kind='transition' AND te.status='committed' AND te.version_before=proof.run_version AND te.version_after=r.control_version AND te.step_after=r.current_step_key AND te.request_key_sha256=mission_internal.request_key_sha256(proof.request_key))
 OR mission_factory_owner.human_ordinary_source_v1(p_session,true) IS NULL OR NOT EXISTS(SELECT 1 FROM mission_generic_owner.regia_human_session_optins_v1 o WHERE o.master_session_id=p_session AND o.actor_user=m.master_user)
 THEN RETURN false;END IF;

 IF mission_factory_owner.human_ordinary_source_v1(p_session,true) IS NULL
 OR proof.source_sha256 IS DISTINCT FROM q.source_sha256 OR proof.run_version IS DISTINCT FROM he.run_control_version OR proof.step_key IS DISTINCT FROM he.step_key
 OR proof.actor_user IS DISTINCT FROM m.master_user OR ev.scope_id IS DISTINCT FROM p_session OR ev.caller IS DISTINCT FROM proof.actor_user OR ev.caller_kind IS DISTINCT FROM 'human' OR ev.caller_service_capability IS NOT NULL
 OR ev.request_key IS DISTINCT FROM extensions.uuid_generate_v5(proof.request_key,'human-combat-close') OR ev.status IS DISTINCT FROM 'completata' OR ev.operation_kind IS DISTINCT FROM 'mission_human_combat_close' OR public.combat_v2_sha256(to_jsonb(ev)) IS DISTINCT FROM proof.event_sha256
 OR ev.result#>>'{data,outcome}' IS DISTINCT FROM 'peaceful' OR ev.result#>>'{data,encounter_id}' IS DISTINCT FROM p_encounter::text
 OR ev.result#>>'{data,step_key}' IS DISTINCT FROM proof.step_key OR ev.result#>>'{data,run_version}' IS DISTINCT FROM proof.run_version::text
 OR NOT EXISTS(SELECT 1 FROM public.combat_v2_sessions WHERE id=p_encounter AND master_session_id=p_session AND state='chiuso' AND closed_at IS NOT NULL)
 OR NOT EXISTS(SELECT 1 FROM public.combat_v2_rounds rr JOIN public.combat_v2_round_reports rep ON rep.id=rr.report_id
 WHERE rr.id=proof.narrated_round_id AND rr.session_id=p_encounter AND rr.state='narrato' AND rep.id=proof.report_id AND rep.mechanics_sha256=proof.report_sha256
 AND rep.narration_state='pubblicata' AND rep.message_id=proof.fato_message_id)
 OR NOT EXISTS(SELECT 1 FROM public.messages msg WHERE msg.id=proof.fato_message_id AND msg.location_id=m.location_id AND msg.kind='fato' AND public.combat_v2_sha256(jsonb_build_object('body',msg.body))=proof.fato_sha256)
 OR EXISTS(SELECT 1 FROM public.combat_v2_resource_ledger WHERE session_id=p_encounter AND is_simulated IS DISTINCT FROM (q.execution_context='staff_simulation'))
 OR EXISTS(SELECT 1 FROM public.combat_v2_rounds rr WHERE rr.session_id=p_encounter AND rr.state<>'narrato' AND (proof.abandoned_round_id IS NULL OR rr.id<>proof.abandoned_round_id))
 THEN RETURN false;END IF;
 IF proof.abandoned_round_id IS NOT NULL AND (
 NOT EXISTS(SELECT 1 FROM public.combat_v2_rounds WHERE id=proof.abandoned_round_id AND session_id=p_encounter AND state='raccolta_azioni' AND phase='raccolta_azioni' AND report_id IS NULL AND freeze_at IS NULL AND resolved_at IS NULL AND narrated_at IS NULL)
 OR EXISTS(SELECT 1 FROM public.combat_v2_declarations WHERE round_id=proof.abandoned_round_id)
 OR EXISTS(SELECT 1 FROM public.combat_v2_round_reports WHERE round_id=proof.abandoned_round_id)
 OR EXISTS(SELECT 1 FROM public.combat_v2_resource_ledger WHERE round_id=proof.abandoned_round_id)
 OR EXISTS(SELECT 1 FROM public.combat_v2_ratings WHERE round_id=proof.abandoned_round_id)
 OR EXISTS(SELECT 1 FROM public.combat_v2_attack_targets WHERE round_id=proof.abandoned_round_id)
 OR EXISTS(SELECT 1 FROM public.combat_v2_defense_coverages WHERE round_id=proof.abandoned_round_id)
 OR EXISTS(SELECT 1 FROM public.combat_v2_narratives WHERE round_id=proof.abandoned_round_id)
 OR EXISTS(SELECT 1 FROM public.combat_v2_ai_narrative_previews WHERE round_id=proof.abandoned_round_id)
 OR EXISTS(SELECT 1 FROM combat_panel_private.actor_turns WHERE round_id=proof.abandoned_round_id AND (main_declaration_id IS NOT NULL OR state<>'ready'))
 ) THEN RETURN false;END IF;
 RETURN true;
END
