CREATE OR REPLACE FUNCTION mission_factory_owner.human_ordinary_release_read_assert_v1(p_release text, p_policy uuid, p_enabled boolean)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare g mission_factory_owner.quest_fixed30_admission; rel mission_public_owner.release_admissions_v1; checked jsonb;observation jsonb;
begin
 select * into strict rel from mission_public_owner.release_admissions_v1 where release_sha256=p_release;
 if nullif(btrim(rel.independent_review_ref),'') is null or nullif(btrim(rel.staff_evidence_ref),'') is null
 or rel.contract_version<>'mission-public-admission/1' then raise exception 'MF_QUEST_PUBLIC_RELEASE_UNQUALIFIED' using errcode='55000';end if;
 checked:=mission_factory_owner.quest_reward_policy_checked_v2(p_policy);
 if p_enabled then
 observation:=mission_factory_owner.human_ordinary_release_identity_v1(p_release,true);IF mission_factory_owner.human_release_observation_valid_v1(observation,p_release,true) IS DISTINCT FROM true THEN RAISE EXCEPTION 'MF_QUEST_CURRENT_OBSERVATION_REQUIRED' USING ERRCODE='55000';END IF;
 if mission_public_owner.human_positive_qualification_v1(p_release,true) is null then raise exception 'MF_QUEST_STAFF_EVIDENCE_NOT_POSITIVE' using errcode='55000';end if;
  select * into strict g from mission_factory_owner.quest_fixed30_admission where singleton;
  if not rel.public_enabled or (not g.public_enabled and (mission_public_owner.human_positive_qualification_v1(p_release,true)->>'schema_version' IS NOT DISTINCT FROM 'human-owner-accepted-release/1') IS DISTINCT FROM true) or g.public_release_sha256 is distinct from p_release
  or (g.public_policy_id is distinct from p_policy AND NOT(EXISTS(SELECT 1 FROM mission_factory_owner.quest_reward_policy_versions hp_new JOIN mission_factory_owner.quest_reward_policy_versions hp_old ON hp_old.id=g.public_policy_id
 WHERE hp_new.id=p_policy AND hp_new.qualified AND hp_old.qualified AND hp_new.scope='staff' AND hp_old.scope='staff' AND hp_new.document_sha256='34197acc065af70dc89ac15d54c19044f4e5af07c91b5869eb0b360a0fcfef19' AND hp_old.document_sha256=hp_new.document_sha256 AND hp_new.document IS NOT DISTINCT FROM hp_old.document AND hp_new.document IS NOT DISTINCT FROM mission_factory_owner.quest_reward_fixed30_document_v2() AND mission_factory_owner.sha(hp_new.document)=hp_new.document_sha256 AND mission_factory_owner.sha(hp_old.document)=hp_old.document_sha256
 AND EXISTS(SELECT 1 FROM mission_factory_owner.quest_fixed30_policy_requests hp_q JOIN mission_factory_owner.catalog_versions hp_cv ON hp_cv.version=hp_q.catalog_version AND hp_cv.active AND hp_cv.qualified AND hp_cv.document_sha256=hp_q.catalog_sha256 AND hp_cv.document_sha256=mission_factory_owner.sha(hp_cv.document) WHERE hp_q.policy_id=hp_new.id AND hp_q.document_sha256=hp_new.document_sha256 )))) or g.public_qualification_sha256 is null
  then raise exception 'MF_QUEST_PUBLIC_RELEASE_UNQUALIFIED' using errcode='55000';end if;
 end if;
end $function$

CREATE OR REPLACE FUNCTION mission_factory_owner.human_ordinary_reward_apply_v1(p_arc uuid, p_terminal_receipt uuid, p_expected_arc_source_sha256 text, p_expected_policy_sha256 text, p_request uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=auth.uid(); actor_role text:=auth.role(); fp text;
 a mission_factory_owner.quest_arcs%rowtype; old mission_factory_owner.quest_reward_requests_v2%rowtype;
 prior mission_factory_owner.quest_reward_decisions_v2%rowtype;
 authority jsonb; eligibility_sha text; recipients uuid[]; cid uuid; mode text; effective integer;
 decision_id uuid:=gen_random_uuid(); award_id uuid; award_receipt jsonb; receipt jsonb; awards jsonb:='[]'::jsonb;
begin
 IF actor_role IS DISTINCT FROM 'authenticated' OR actor IS NULL OR public.is_staff() IS DISTINCT FROM true THEN RAISE EXCEPTION 'HUMAN_ORDINARY_REWARD_NORMAL_MASTER_REQUIRED' USING ERRCODE='42501';END IF;
 SELECT * INTO STRICT a FROM mission_factory_owner.quest_arcs WHERE id=p_arc FOR SHARE;
 IF a.source_document->>'content_kind' IS DISTINCT FROM 'quest_human' OR a.availability_scope IS DISTINCT FROM 'public' OR NOT EXISTS(SELECT 1 FROM mission_factory_owner.quest_run_sources hq WHERE hq.arc_id=a.id AND hq.terminal_receipt_id=p_terminal_receipt AND mission_factory_owner.human_ordinary_source_v1(hq.session_id,true) IS NOT NULL) THEN RAISE EXCEPTION 'HUMAN_ORDINARY_REWARD_OWN_CONFIRMED_SOURCE_REQUIRED' USING ERRCODE='42501';END IF;
 if p_arc is null or p_terminal_receipt is null or p_request is null
    or coalesce(p_expected_arc_source_sha256,'') !~ '^[0-9a-f]{64}$'
    or coalesce(p_expected_policy_sha256,'') !~ '^[0-9a-f]{64}$'
 then raise exception 'MF_FIXED30_INPUT' using errcode='22023'; end if;
 PERFORM mission_factory_owner.human_ordinary_execution_read_assert_v1(p_arc,true);
 fp:=mission_factory_owner.sha(jsonb_build_object('arc_id',p_arc,'terminal_receipt_id',p_terminal_receipt,
   'source_sha256',p_expected_arc_source_sha256,'policy_sha256',p_expected_policy_sha256));
 perform pg_advisory_xact_lock(hashtextextended(p_arc::text,30092633));
 perform pg_advisory_xact_lock(hashtextextended(p_request::text,30092631));
 select * into old from mission_factory_owner.quest_reward_requests_v2 where request_key=p_request for share;
 if found then
   if old.actor_user is distinct from actor or old.actor_role is distinct from actor_role
      or old.fingerprint is distinct from fp or old.arc_id is distinct from p_arc
   then raise exception 'MF_FIXED30_REQUEST_CONFLICT' using errcode='23505'; end if;
   return old.receipt;
 end if;
 select * into strict a from mission_factory_owner.quest_arcs where id=p_arc for update;
 if a.source_sha256 is distinct from p_expected_arc_source_sha256
    or a.reward_policy_sha256 is distinct from p_expected_policy_sha256
 then raise exception 'MF_FIXED30_ARC_CAS' using errcode='40001'; end if;
 select * into prior from mission_factory_owner.quest_reward_decisions_v2 where arc_id=p_arc for share;
 if found then
   if prior.terminal_receipt_id is distinct from p_terminal_receipt or prior.source_sha256 is distinct from a.source_sha256
      or prior.policy_sha256 is distinct from a.reward_policy_sha256
   then raise exception 'MF_FIXED30_EXISTING_AWARD_DRIFT' using errcode='40001'; end if;
   insert into mission_factory_owner.quest_reward_requests_v2(request_key,arc_id,actor_user,actor_role,fingerprint,decision_id,receipt)
   values(p_request,p_arc,actor,actor_role,fp,prior.id,prior.receipt);
   return prior.receipt;
 end if;
 IF NOT EXISTS(SELECT 1 FROM mission_factory_owner.quest_run_sources hq WHERE hq.arc_id=a.id AND hq.terminal_receipt_id=p_terminal_receipt AND hq.state='terminal' AND mission_factory_owner.human_ordinary_source_v1(hq.session_id,true) IS NOT NULL AND mission_factory_owner.c444_terminal_confirmed_v1(hq.session_id)=(SELECT ht.receipt FROM mission_factory_owner.quest_terminal_receipts ht WHERE ht.id=p_terminal_receipt)) THEN RAISE EXCEPTION 'HUMAN_ORDINARY_REWARD_BINDING_UNPROVEN' USING ERRCODE='42501';END IF;
 authority:=mission_factory_owner.human_ordinary_reward_authority_v1(p_arc,p_terminal_receipt);
 mode:=authority->>'effect_mode'; eligibility_sha:=mission_factory_owner.sha(authority);
 select array_agg(value::uuid order by value::uuid) into recipients
 from jsonb_array_elements_text(authority->'recipients');
 perform 1 from public.characters where id=any(recipients) order by id for update;
 if (select count(*) from public.characters where id=any(recipients))<>cardinality(recipients)
 then raise exception 'MF_FIXED30_CHARACTER_MISSING' using errcode='40001'; end if;
 -- Insert the decision once, then claims and credits atomically; deferred receipt-freeze is not needed.
 receipt:=jsonb_build_object('schema_version','quest-arc-reward-receipt/2','decision_id',decision_id,
   'arc_id',p_arc,'terminal_receipt_id',p_terminal_receipt,'outcome',authority->>'outcome',
   'source_sha256',a.source_sha256,'policy_id',a.reward_policy_id,'policy_sha256',a.reward_policy_sha256,
   'eligibility_sha256',eligibility_sha,'recipient_count',cardinality(recipients),
   'state',case when mode='simulation' then 'simulated' else 'applied' end,'effect_mode',mode,
   'computed_xp_per_recipient',30,'effective_xp_per_recipient',case when mode='simulation' then 0 else 30 end,
   'ryo_per_recipient',0,'items','[]'::jsonb);
 insert into mission_factory_owner.quest_reward_decisions_v2(id,arc_id,terminal_receipt_id,policy_id,policy_sha256,
   source_sha256,eligibility_document,eligibility_sha256,recipients,effect_mode,receipt)
 values(decision_id,p_arc,p_terminal_receipt,a.reward_policy_id,a.reward_policy_sha256,a.source_sha256,
   authority,eligibility_sha,recipients,mode,receipt);
 foreach cid in array recipients loop
   award_id:=gen_random_uuid();
   award_receipt:=jsonb_build_object('schema_version','quest-recipient-reward/2','award_id',award_id,'decision_id',decision_id,
     'arc_id',p_arc,'character_id',cid,'effect_mode',mode,'computed_xp',30,
     'effective_xp',case when mode='simulation' then 0 else 30 end,'ryo',0,'items','[]'::jsonb);
   insert into mission_factory_owner.quest_reward_awards_v2(id,decision_id,arc_id,character_id,computed_xp,effective_xp,effect_mode,ryo,items,receipt)
   values(award_id,decision_id,p_arc,cid,30,case when mode='simulation' then 0 else 30 end,mode,0,'[]'::jsonb,award_receipt);
   effective:=mission_factory_owner.quest_reward_credit_v2(cid,mode);
   if effective is distinct from (award_receipt->>'effective_xp')::integer
   then raise exception 'MF_FIXED30_CREDIT_RECEIPT_DRIFT' using errcode='40001'; end if;
 end loop;
 insert into mission_factory_owner.quest_reward_requests_v2(request_key,arc_id,actor_user,actor_role,fingerprint,decision_id,receipt)
 values(p_request,p_arc,actor,actor_role,fp,decision_id,receipt);
 return receipt;
end;
$function$

CREATE OR REPLACE FUNCTION mission_factory_owner.human_ordinary_reward_authority_v1(p_arc uuid, p_terminal uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare a mission_factory_owner.quest_arcs%rowtype;
 q mission_factory_owner.quest_run_sources%rowtype; tr mission_factory_owner.quest_terminal_receipts%rowtype;
 proofs jsonb:='[]'::jsonb; recipients uuid[]:='{}'::uuid[]; final_terminal uuid; final_outcome text; final_roster uuid[];
 users uuid[]; latest_ordinal integer:=0; checked jsonb;
begin
 select * into strict a from mission_factory_owner.quest_arcs where id=p_arc for share;
 if a.source_document->>'content_kind' IS DISTINCT FROM 'quest_human' OR a.availability_scope IS DISTINCT FROM 'public' OR a.state not in('completed','failed') or a.source_sha256 is distinct from mission_factory_owner.sha(a.source_document)
 then raise exception 'MF_FIXED30_ARC_NOT_TERMINAL' using errcode='55000'; end if;
 if a.availability_scope='public' then perform mission_factory_owner.quest_execution_assert_v4(a.id,true);end if;
 checked:=mission_factory_owner.quest_reward_policy_checked_v2(a.reward_policy_id);
 if checked->>'policy_sha256' is distinct from a.reward_policy_sha256
 then raise exception 'MF_FIXED30_POLICY_PIN_DRIFT' using errcode='40001'; end if;
 for q in select * from mission_factory_owner.quest_run_sources where arc_id=p_arc order by episode_ordinal for share loop
   if q.state in('prepared','cancelled') and q.start_event_id is null and q.started_at is null then continue; end if;
   if q.state<>'terminal' or q.started_at is null or q.terminal_at is null
      or q.start_event_id is null or q.opening_publication_id is null or q.terminal_receipt_id is null
   then raise exception 'MF_FIXED30_PARTICIPATION_UNCERTAIN' using errcode='55000'; end if;
   perform mission_factory_owner.quest_run_source_assert_v1(q.session_id);
   -- Source availability, exact release and Native terminal authority determine resource mode.
   if not exists(select 1 from public.locations l where l.id=q.location_id and l.is_test=mission_factory_owner.quest_is_simulation_v4(q.arc_id) and l.is_active)
   then raise exception 'MF_FIXED30_REAL_ROUTE_NOT_QUALIFIED' using errcode='55000'; end if;
   select * into strict tr from mission_factory_owner.quest_terminal_receipts
      where id=q.terminal_receipt_id and session_id=q.session_id and episode_id=q.episode_id for share;
   if mission_factory_owner.c444_terminal_confirmed_v1(q.session_id) is distinct from tr.receipt
      or not exists(select 1 from public.mission_run_publications p
        where p.id=q.opening_publication_id and p.event_id=q.start_event_id
          and p.master_session_id=q.session_id and p.status='committed')
      or not exists(select 1 from public.mission_run_messages msg where msg.publication_id=q.opening_publication_id)
      or q.roster_snapshot_sha256 is distinct from mission_factory_owner.sha(to_jsonb(q.roster_character_ids))
      or exists(select 1 from unnest(q.roster_character_ids) x(id)
        join public.characters c on c.id=x.id
        where not exists(select 1 from public.master_v2_participants mp
          where mp.session_id=q.session_id and mp.character_id=c.id
            and mp.user_id_snapshot=c.user_id and mp.joined_at<=q.started_at))
   then raise exception 'MF_FIXED30_PARTICIPATION_PROOF_DRIFT' using errcode='40001'; end if;
   if exists(select 1 from public.master_v2_participants mp
     where mp.session_id=q.session_id and mp.character_id=any(q.roster_character_ids)
       and mp.left_at is not null AND NOT (mission_factory_owner.human_ordinary_source_v1(q.session_id,true) IS NOT NULL AND mp.engagement_state='concluso' AND EXISTS(SELECT 1 FROM public.master_v2_sessions hm WHERE hm.id=q.session_id AND hm.closed_at IS NOT NULL AND mp.left_at>=hm.closed_at) AND mission_factory_owner.c444_terminal_confirmed_v1(q.session_id)=tr.receipt))
   then raise exception 'MF_FIXED30_ELIGIBILITY_UNQUALIFIED' using errcode='55000'; end if;
   if mission_factory_owner.quest_is_simulation_v4(q.arc_id) and exists(select 1 from public.characters c where c.id=any(q.roster_character_ids)
     and not exists(select 1 from mission_factory_owner.quest_fixed30_admission ad
       where ad.singleton and ad.public_staff_enabled AND ad.public_staff_release_sha256=a.public_release_sha256 AND ad.public_staff_qualification_sha256=a.execution_qualification_sha256 AND c.user_id=ANY(a.execution_auth_ids)))
   then raise exception 'MF_FIXED30_STAFF_AUTH_SCOPE' using errcode='42501';end if;
   recipients:=recipients||q.roster_character_ids;
   final_roster:=q.roster_character_ids;
   proofs:=proofs||jsonb_build_array(jsonb_build_object('episode_id',q.episode_id,
      'session_id',q.session_id,'ordinal',q.episode_ordinal,'source_sha256',q.source_sha256,
      'roster_ids',q.roster_character_ids,'roster_sha256',q.roster_snapshot_sha256,
      'start_event_id',q.start_event_id,'opening_publication_id',q.opening_publication_id,
      'terminal_receipt_id',tr.id,'terminal_publication_id',tr.publication_id));
   latest_ordinal:=q.episode_ordinal; final_terminal:=tr.id; final_outcome:=tr.outcome;
 end loop;
 select array_agg(distinct id order by id) into recipients from unnest(recipients)x(id);
 if exists(select 1 from unnest(recipients)x(id) where not(x.id=any(final_roster)))
 then raise exception 'MF_FIXED30_ELIGIBILITY_UNQUALIFIED' using errcode='55000'; end if;
 -- L'union prova il corpus storico; casi usciti/abbandonati rimangono UNKNOWN, non esclusi o premiati.
 if recipients is null or cardinality(recipients) not between 1 and 128 or final_terminal is distinct from p_terminal
   or final_outcome is distinct from (case when a.state='completed' then 'success' else 'failure' end)
   or (a.state='completed' and exists(select 1 from mission_factory_owner.quest_episodes ep
      where ep.arc_id=a.id and ep.ordinal>latest_ordinal))
 then raise exception 'MF_FIXED30_FINAL_RECEIPT_DRIFT' using errcode='40001'; end if;
 return jsonb_build_object('schema_version','quest-reward-eligibility/2','arc_id',a.id,
   'source_sha256',a.source_sha256,'policy_id',a.reward_policy_id,'policy_sha256',a.reward_policy_sha256,
   'terminal_receipt_id',p_terminal,'outcome',final_outcome,'recipients',recipients,
   'proofs',proofs,'effect_mode',case when mission_factory_owner.quest_is_simulation_v4(a.id) then 'simulation' else 'real' end,
   'technical_interpretation','PM: tutti i PG degli snapshot delle puntate effettivamente avviate e concluse, una volta per arco; nessuna scelta umana specifica sugli abbandoni');
end;
$function$

CREATE OR REPLACE FUNCTION mission_factory_owner.human_ordinary_source_v1(p_session uuid, p_master boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE command_context jsonb;
BEGIN
 IF EXISTS(SELECT 1 FROM mission_factory_owner.quest_run_sources history_source WHERE session_id=p_session AND state IN('terminal','cancelled')) THEN

DECLARE q mission_factory_owner.quest_run_sources;a mission_factory_owner.quest_arcs;m public.master_v2_sessions;
 b mission_factory_owner.c384_human_bindings;loc public.locations;u uuid:=auth.uid();proof jsonb;policy mission_factory_owner.quest_reward_policy_versions;
BEGIN
 IF u IS NULL OR auth.role() IS DISTINCT FROM 'authenticated' OR p_session IS NULL OR p_master IS NULL THEN RETURN NULL;END IF;
