BEGIN
 IF auth.uid() IS NULL OR auth.role() IS DISTINCT FROM 'authenticated' THEN RAISE EXCEPTION 'HUMAN_ORDINARY_NORMAL_AUTHOR_REQUIRED' USING ERRCODE='42501';END IF;
