BEGIN
 IF auth.uid() IS NULL OR auth.role() IS DISTINCT FROM 'authenticated' OR public.is_staff() IS DISTINCT FROM true OR p_episode IS NULL OR p_request IS NULL OR p_operation NOT IN('prepare','optin','start') THEN RAISE EXCEPTION 'HUMAN_ORDINARY_LIFECYCLE_NORMAL_MASTER_REQUIRED' USING ERRCODE='42501';END IF;
 SELECT * INTO STRICT e FROM mission_factory_owner.quest_episodes WHERE id=p_episode;
