 PERFORM mission_factory_owner.c444_source_read_assert_v1(q.session_id);
 IF p_operation='prepare' AND q.prepare_request_key=p_request THEN
 receipt:=jsonb_build_object('schema_version','quest-human-episode-prepare/1','request_key',p_request,'state','prepared','quest_arc_id',q.arc_id,'quest_episode_id',q.episode_id,'native_session_id',q.session_id,'source_sha256',q.source_sha256,'plan_version_id',q.plan_version_id,'plan_sha256',q.plan_sha256,'roster_snapshot_sha256',q.roster_snapshot_sha256,'staff_release_sha256',q.staff_release_sha256,'location_id',q.location_id,'control_version',1,'opening_publication_id',NULL);
 ELSIF p_operation='start' AND q.start_request_key=p_request THEN
