 IF ev.result->>'schema_version' IS DISTINCT FROM 'quest-human-episode-start/1' OR ev.result->>'prepare_request_key' IS DISTINCT FROM q.prepare_request_key::text OR ev.result->>'native_session_id' IS DISTINCT FROM q.session_id::text THEN RAISE EXCEPTION 'HUMAN_ORDINARY_HISTORICAL_START_DRIFT' USING ERRCODE='40001';END IF;receipt:=ev.result;
 ELSIF p_operation='optin' THEN
