 IF FOUND THEN IF j.receipt_sha256 IS DISTINCT FROM mission_factory_owner.sha(j.receipt) OR j.receipt->>'native_session_id' IS DISTINCT FROM q.session_id::text OR NOT EXISTS(SELECT 1 FROM mission_generic_owner.regia_human_session_optins_v1 n WHERE n.master_session_id=q.session_id AND n.actor_user=j.actor_user AND n.request_key=j.request_key) THEN RAISE EXCEPTION 'HUMAN_ORDINARY_HISTORICAL_OPTIN_DRIFT' USING ERRCODE='40001';END IF;receipt:=j.receipt;END IF;
 END IF;END IF;
 RETURN jsonb_build_object('schema_version','human-ordinary-lifecycle-receipt/1','quest_episode_id',p_episode,'request_key',p_request,'operation',p_operation,'state',CASE WHEN receipt IS NULL THEN 'not_found' ELSE 'committed' END,'receipt',receipt);
