CREATE OR REPLACE FUNCTION public.mission_factory_quest_human_ordinary_terminal_publish_v1(p_session uuid, p_event uuid, p_body text, p_request uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE source jsonb;terminal jsonb;reward jsonb;a mission_factory_owner.quest_arcs;reward_request uuid;
BEGIN
 source:=mission_factory_owner.human_ordinary_source_v1(p_session,true);
 IF source IS NULL OR auth.role() IS DISTINCT FROM 'authenticated' OR public.is_staff() IS DISTINCT FROM true
 THEN RAISE EXCEPTION 'HUMAN_ORDINARY_TERMINAL_NORMAL_MASTER_REQUIRED' USING ERRCODE='42501';END IF;
 terminal:=mission_factory_owner.human_ordinary_terminal_core_v1(p_session,p_event,p_body,p_request);
 SELECT * INTO STRICT a FROM mission_factory_owner.quest_arcs WHERE id=(source->>'quest_arc_id')::uuid FOR SHARE;
 IF a.state IN('completed','failed') AND mission_factory_owner.human_ordinary_final_terminal_v1(a.id) IS NOT DISTINCT FROM (terminal->>'native_terminal_receipt_id')::uuid THEN
  reward_request:=extensions.uuid_generate_v5(p_request,'human-ordinary-fixed30/1');
  BEGIN
   reward:=mission_factory_owner.human_ordinary_reward_apply_v1(a.id,(terminal->>'native_terminal_receipt_id')::uuid,a.source_sha256,a.reward_policy_sha256,reward_request);
  EXCEPTION WHEN SQLSTATE '55000' THEN
   IF SQLERRM NOT IN('MF_FIXED30_ELIGIBILITY_UNQUALIFIED','MF_FIXED30_PARTICIPATION_UNCERTAIN','MF_FIXED30_STAFF_NOT_QUALIFIED') THEN RAISE;END IF;
   reward:=jsonb_build_object('schema_version','quest-arc-reward-deferred/2','arc_id',a.id,'terminal_receipt_id',terminal->>'native_terminal_receipt_id','request_key',reward_request,'state','pending_award','reason_code',SQLERRM);
  END;
 END IF;
 RETURN jsonb_build_object('schema_version','quest-terminal-with-reward/2','terminal',terminal,'reward',reward);
END $function$

CREATE OR REPLACE FUNCTION public.mission_factory_quest_human_regia_optin_v1(p_session uuid, p_expected_control_version bigint, p_expected_source_sha256 text, p_request uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE m public.master_v2_sessions;q mission_factory_owner.quest_run_sources;
 r public.mission_run_state;j mission_factory_owner.c463_optin_receipts;
 n mission_generic_owner.regia_human_session_optins_v1;identity jsonb;fp text;receipt jsonb;
 location uuid;users uuid[];prepared mission_factory_owner.c395_prepared_sources;
BEGIN
 IF auth.uid() IS NULL OR auth.role() IS DISTINCT FROM 'authenticated' THEN RAISE EXCEPTION 'C463_NORMAL_AUTH_REQUIRED' USING ERRCODE='42501';END IF;
 IF p_session IS NULL OR p_request IS NULL OR p_expected_control_version IS NULL OR p_expected_control_version<1
 OR p_expected_source_sha256 IS NULL OR p_expected_source_sha256!~'^[0-9a-f]{64}$'
 THEN RAISE EXCEPTION 'C463_OPTIN_INPUT' USING ERRCODE='22023';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(p_request::text,46301));
 -- Same location/session lock order as Native Human start; immutable authority before replay, never active_assert here.
 SELECT location_id INTO STRICT location FROM mission_factory_owner.quest_run_sources WHERE session_id=p_session;
 PERFORM 1 FROM public.locations WHERE id=location FOR UPDATE;
 PERFORM public.master_v2_lock_scope(p_session);
 SELECT * INTO STRICT m FROM public.master_v2_sessions WHERE id=p_session FOR UPDATE;
 SELECT * INTO STRICT q FROM mission_factory_owner.quest_run_sources WHERE session_id=p_session FOR UPDATE;
 identity:=mission_factory_owner.c463_optin_identity_v1(p_session);
 IF q.source_sha256 IS DISTINCT FROM p_expected_source_sha256 THEN RAISE EXCEPTION 'C463_OPTIN_SOURCE_CAS' USING ERRCODE='40001';END IF;
 fp:=mission_factory_owner.sha(jsonb_build_object('schema_version','quest-human-regia-optin-request/1','native_session_id',p_session,'request_key',p_request,
 'expected_control_version',p_expected_control_version,'expected_source_sha256',p_expected_source_sha256,'actor_user',auth.uid(),'identity_sha256',mission_factory_owner.sha(identity)));
 SELECT * INTO j FROM mission_factory_owner.c463_optin_receipts WHERE request_key=p_request;
 IF FOUND THEN
  IF j.session_id IS DISTINCT FROM p_session OR j.actor_user IS DISTINCT FROM auth.uid()
  OR j.expected_control_version IS DISTINCT FROM p_expected_control_version OR j.request_sha256 IS DISTINCT FROM fp
  THEN RAISE EXCEPTION 'C463_OPTIN_REQUEST_CONFLICT' USING ERRCODE='40001';END IF;
  RETURN public.mission_factory_quest_human_regia_optin_receipt_v1(p_session,p_request)->'receipt';
 END IF;
 -- New write only: finite named scope, full Source, current Staff presence/protection, prepared-state CAS and no Native encounter.
 IF (NOT EXISTS(SELECT 1 FROM mission_factory_owner.c463_optin_control c WHERE c.singleton AND c.enabled
 AND c.bound_at<=statement_timestamp() AND c.expires_at>statement_timestamp() AND auth.uid()=ANY(c.master_user_ids) AND p_session=ANY(c.session_ids)) AND mission_factory_owner.human_ordinary_source_v1(p_session,true) IS NULL)
 OR NOT EXISTS(SELECT 1 FROM mission_factory_owner.c395_control WHERE singleton AND prepare_enabled)
 OR NOT EXISTS(SELECT 1 FROM mission_factory_owner.c384_control WHERE singleton AND enabled)
 OR NOT EXISTS(SELECT 1 FROM mission_factory_owner.c407_control WHERE singleton AND admission_enabled)
 OR NOT EXISTS(SELECT 1 FROM mission_factory_owner.c412_control WHERE singleton AND runtime_enabled)
 OR ((NOT mission_factory_owner.c444_enabled_v1() OR mission_factory_owner.c416_kind_live_v1() IS DISTINCT FROM true) AND mission_factory_owner.human_ordinary_source_v1(p_session,true) IS NULL)
 THEN RAISE EXCEPTION 'C463_OPTIN_DISABLED_OR_EXPIRED' USING ERRCODE='42501';END IF;
 PERFORM mission_factory_owner.assert_editor(auth.uid());
 PERFORM mission_factory_owner.c395_source_assert_v1(p_session);
 SELECT * INTO STRICT prepared FROM mission_factory_owner.c395_prepared_sources WHERE session_id=p_session FOR SHARE;
 SELECT * INTO STRICT r FROM public.mission_run_state WHERE master_session_id=p_session FOR UPDATE;
 SELECT array_agg(c.user_id ORDER BY x.ord) INTO users FROM unnest(q.roster_character_ids) WITH ORDINALITY x(id,ord) JOIN public.characters c ON c.id=x.id AND c.user_id IS NOT NULL;
 IF m.location_id IS DISTINCT FROM location OR q.location_id IS DISTINCT FROM location
 OR m.stato IS DISTINCT FROM 'preparazione' OR q.state IS DISTINCT FROM 'prepared' OR q.start_request_key IS NOT NULL
 OR m.closed_at IS NOT NULL OR m.suspended_at IS NOT NULL OR m.control_version IS DISTINCT FROM p_expected_control_version
 OR q.control_version IS DISTINCT FROM p_expected_control_version OR r.control_version IS DISTINCT FROM p_expected_control_version
 OR r.run_phase IS DISTINCT FROM 'preparazione' OR r.source_kind IS DISTINCT FROM 'quest' OR r.mission_id IS NOT NULL
 OR r.quest_episode_id IS DISTINCT FROM q.episode_id OR r.plan_version_id IS DISTINCT FROM q.plan_version_id
 OR prepared.assigned_master IS DISTINCT FROM auth.uid() OR prepared.prepare_request IS DISTINCT FROM q.prepare_request_key
 OR p_request=q.prepare_request_key OR cardinality(users) IS DISTINCT FROM cardinality(q.roster_character_ids)
 OR ((NOT EXISTS(SELECT 1 FROM public.locations WHERE id=location AND is_active AND is_test) OR combat_consumer_private.staff_test_allowed(location,array_append(users,auth.uid()),false) IS DISTINCT FROM true) AND mission_factory_owner.human_ordinary_source_v1(p_session,true) IS NULL)
 OR EXISTS(SELECT 1 FROM mission_creation_owner.human_encounters WHERE master_session_id=p_session)
 OR EXISTS(SELECT 1 FROM public.combat_v2_sessions WHERE master_session_id=p_session AND state NOT IN('chiuso','annullato'))
 THEN RAISE EXCEPTION 'C463_OPTIN_PREPARED_STAFF_CAS_REQUIRED' USING ERRCODE='40001';END IF;
 SELECT * INTO n FROM mission_generic_owner.regia_human_session_optins_v1 WHERE master_session_id=p_session FOR UPDATE;
 IF FOUND THEN RAISE EXCEPTION 'C463_NATIVE_OPTIN_ALREADY_RESERVED' USING ERRCODE='40001';END IF;
 INSERT INTO mission_generic_owner.regia_human_session_optins_v1(master_session_id,actor_user,request_key) VALUES(p_session,auth.uid(),p_request);
 receipt:=jsonb_build_object('schema_version','quest-human-regia-optin/1','native_session_id',p_session,'request_key',p_request,'status','reserved',
 'assigned_master',auth.uid(),'source_sha256',q.source_sha256,'prepare_request_key',q.prepare_request_key,'expected_control_version',p_expected_control_version,
 'roster_snapshot_sha256',q.roster_snapshot_sha256,'identity_sha256',mission_factory_owner.sha(identity));
 INSERT INTO mission_factory_owner.c463_optin_receipts(session_id,request_key,actor_user,expected_control_version,source_sha256,identity_sha256,request_sha256,receipt,receipt_sha256)
 VALUES(p_session,p_request,auth.uid(),p_expected_control_version,q.source_sha256,mission_factory_owner.sha(identity),fp,receipt,mission_factory_owner.sha(receipt));
 RETURN receipt;
END $function$

CREATE OR REPLACE FUNCTION public.mission_factory_quest_human_route_v1(p_episode uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE e mission_factory_owner.quest_episodes;a mission_factory_owner.quest_arcs;h mission_factory_owner.c416_human_draft_sources;modes text[]:='{}'::text[];
BEGIN
 IF auth.uid() IS NULL OR auth.role() IS DISTINCT FROM 'authenticated' OR p_episode IS NULL THEN RAISE EXCEPTION 'QUEST_HUMAN_ROUTE_NORMAL_AUTH_REQUIRED' USING ERRCODE='42501';END IF;
 SELECT * INTO STRICT e FROM mission_factory_owner.quest_episodes WHERE id=p_episode;
 SELECT * INTO STRICT a FROM mission_factory_owner.quest_arcs WHERE id=e.arc_id;
 SELECT * INTO STRICT h FROM mission_factory_owner.c416_human_draft_sources WHERE draft_id=a.draft_id;
 IF a.source_document->>'content_kind' IS DISTINCT FROM 'quest_human' OR a.source_sha256 IS DISTINCT FROM h.human_document_sha256 OR e.source_sha256 IS DISTINCT FROM mission_factory_owner.sha(e.source_document) OR a.availability_scope NOT IN('staff','public') OR a.execution_context NOT IN('staff_simulation','public_real') OR (a.availability_scope='staff' AND a.execution_context IS DISTINCT FROM 'staff_simulation') THEN RAISE EXCEPTION 'QUEST_HUMAN_ROUTE_TYPED_SOURCE_REQUIRED' USING ERRCODE='42501';END IF;
 IF h.author_user=auth.uid() AND public.master_v2_is_master(auth.uid()) IS TRUE THEN modes:=array_append(modes,'master');END IF;
 IF EXISTS(SELECT 1 FROM public.characters c WHERE c.user_id=auth.uid() AND c.id=ANY(e.member_character_ids)) THEN modes:=array_append(modes,'participant');END IF;
 IF cardinality(modes)=0 THEN RAISE EXCEPTION 'QUEST_HUMAN_ROUTE_OWN_AUTHOR_OR_ROSTER_REQUIRED' USING ERRCODE='42501';END IF;
 PERFORM mission_factory_owner.c416_arc_assert_v1(a.id,false);
 RETURN jsonb_build_object('schema_version','quest-human-route/1','quest_episode_id',e.id,'content_kind','quest_human','availability_scope',a.availability_scope,'execution_context',a.execution_context,'viewer_modes',to_jsonb(modes));
END $function$

