 IF p_session IS NULL THEN RAISE EXCEPTION 'C470_SESSION_REQUIRED' USING ERRCODE='22023';END IF;
 -- Master identity remains distinct from PG identity, including the same normal Auth account.
 PERFORM mission_factory_owner.c407_identity_v1(p_session);
 PERFORM mission_factory_owner.c444_source_read_assert_v1(p_session);
 SELECT * INTO STRICT q FROM mission_factory_owner.quest_run_sources WHERE session_id=p_session FOR SHARE;
 SELECT * INTO STRICT b FROM mission_factory_owner.c384_human_bindings WHERE session_id=p_session FOR SHARE;
 SELECT * INTO STRICT av FROM mission_factory_owner.c384_authoring_versions WHERE lineage_id=b.lineage_id AND version=b.authoring_version FOR SHARE;
 SELECT * INTO STRICT a FROM mission_factory_owner.quest_arcs WHERE id=q.arc_id FOR SHARE;
 IF b.assigned_master IS DISTINCT FROM auth.uid() OR av.author_user IS DISTINCT FROM auth.uid()
 OR av.document_sha256 IS DISTINCT FROM mission_factory_owner.sha(av.document)
 OR av.document_sha256 IS DISTINCT FROM b.binding_snapshot->>'authoring_sha256'
 OR b.binding_sha256 IS DISTINCT FROM mission_factory_owner.sha(b.binding_snapshot)
 OR b.episode_id IS DISTINCT FROM q.episode_id OR b.source_sha256 IS DISTINCT FROM q.source_sha256
 THEN RAISE EXCEPTION 'C470_IMMUTABLE_AUTHORING_IDENTITY_REQUIRED' USING ERRCODE='42501';END IF;
 IF q.state='terminal' THEN term:=mission_factory_owner.c444_terminal_confirmed_v1(p_session);END IF;
 IF term IS NOT NULL AND a.quest_kind='trama' THEN
  SELECT * INTO ne FROM mission_factory_owner.quest_episodes WHERE arc_id=q.arc_id AND ordinal=q.episode_ordinal+1 FOR SHARE;
  IF ne.id IS NOT NULL AND (ne.source_sha256 IS DISTINCT FROM mission_factory_owner.sha(ne.source_document)
   OR ne.member_character_ids IS DISTINCT FROM q.roster_character_ids) THEN
   RAISE EXCEPTION 'C470_SUCCESSOR_SOURCE_OR_IMMUTABLE_ROSTER_DRIFT' USING ERRCODE='40001';END IF;
 END IF;
 why:=CASE
  WHEN (NOT mission_factory_owner.c444_enabled_v1() OR mission_factory_owner.c416_kind_live_v1() IS DISTINCT FROM true) AND mission_factory_owner.human_ordinary_source_v1(p_session,true) IS NULL THEN 'DISABLED'
  WHEN q.state<>'terminal' THEN 'CURRENT_EPISODE_NOT_TERMINAL'
  WHEN term IS NULL THEN 'TERMINAL_PUBLICATION_NOT_CONFIRMED'
  WHEN ne.id IS NULL THEN 'NO_SUCCESSOR'
  WHEN NOT EXISTS(SELECT 1 FROM mission_factory_owner.c395_control WHERE singleton AND prepare_enabled)
   OR NOT EXISTS(SELECT 1 FROM mission_factory_owner.c384_control WHERE singleton AND enabled) THEN 'HUMAN_PREPARE_DISABLED'
  WHEN EXISTS(SELECT 1 FROM mission_factory_owner.quest_run_sources WHERE episode_id=ne.id) THEN 'SUCCESSOR_ALREADY_PREPARED'
  WHEN mission_factory_owner.c444_enrollment_open_v1(ne.id) IS DISTINCT FROM true THEN 'NATIVE_ENROLLMENT_CLOSED'
  ELSE 'READY' END;
 ready:=why='READY';
 RETURN jsonb_build_object('schema_version','quest-human-successor-scope/1',
  'from_session_id',p_session,'quest_arc_id',q.arc_id,
  'next_episode_id',ne.id,'next_ordinal',ne.ordinal,
  'lineage_id',CASE WHEN ne.id IS NOT NULL THEN b.lineage_id ELSE NULL END,
  'authoring_version',CASE WHEN ne.id IS NOT NULL THEN b.authoring_version ELSE NULL END,
  'next_source_sha256',ne.source_sha256,
  'previous_terminal_receipt_id',CASE WHEN term IS NOT NULL THEN q.terminal_receipt_id ELSE NULL END,
  'location_id',q.location_id,'roster_character_ids',to_jsonb(q.roster_character_ids),
  'eligible',ready,'reason_code',why);
END $function$

CREATE OR REPLACE FUNCTION public.mission_factory_save_v1(p_draft uuid, p_expected_version bigint, p_document jsonb, p_request uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare d mission_factory_owner.drafts; prior mission_factory_owner.requests;
        doc jsonb; fp text; result jsonb; next_version bigint;
begin
  select * into strict d from mission_factory_owner.drafts where id=p_draft;
  perform mission_factory_owner.assert_editor(d.author_user);
  if d.document->>'schema_version' is distinct from 'mission-factory-draft/2' then
    if p_document->>'schema_version'='mission-factory-draft/2'
      then raise exception 'MF_KIND_MISMATCH' using errcode='22023'; end if;
    return mission_factory_owner.legacy_save_v1(p_draft,p_expected_version,p_document,p_request);
  end if;
  if p_request is null or p_document->>'content_kind' is distinct from 'quest_ai'
     or p_document->>'schema_version' is distinct from 'mission-factory-draft/2'
    then raise exception 'MF_KIND_MISMATCH' using errcode='22023'; end if;
  doc:=mission_factory_owner.validate_quest_draft_v2(p_document);
  fp:=mission_factory_owner.sha(jsonb_build_object('op','save','draft_id',p_draft,
    'expected_version',p_expected_version,'document',doc));
  perform pg_advisory_xact_lock(hashtextextended(p_request::text,24092027));
  select * into prior from mission_factory_owner.requests where request_key=p_request;
  if found then
    if prior.actor_user<>auth.uid() or prior.operation<>'save' or prior.fingerprint<>fp
      then raise exception 'MF_REQUEST_CONFLICT' using errcode='40001'; end if;
    return prior.result;
  end if;
  IF (public.is_staff() IS TRUE AND auth.role()='authenticated' AND d.author_user=auth.uid() AND mission_factory_owner.human_custom_ordinary_capability_v1(p_draft,false) IS NOT NULL) IS DISTINCT FROM true THEN
  perform mission_factory_owner.manual_authoring_assert_v1('save',null);
  END IF;

  select * into strict d from mission_factory_owner.drafts where id=p_draft for update;
  perform mission_factory_owner.assert_editor(d.author_user);
  if d.document->>'schema_version' is distinct from 'mission-factory-draft/2'
     or d.document->>'content_kind' is distinct from 'quest_ai'
     or d.state not in('draft','previewed')
     or d.control_version<>p_expected_version
     or d.catalog_version is distinct from doc->>'catalog_version'
     or d.document#>>'{quest,quest_kind}' is distinct from doc#>>'{quest,quest_kind}'
     or d.document#>>'{quest,roster_assignment_id}' is distinct from doc#>>'{quest,roster_assignment_id}'
     or d.document->'variants' is distinct from doc->'variants'
    then raise exception 'MF_DRAFT_DRIFT' using errcode='40001'; end if;
  -- Il roster si cambia solo tramite porta Staff CAS dedicata, non nel salvataggio JSON.
  update mission_factory_owner.drafts set document=doc,document_sha256=mission_factory_owner.sha(doc),
    control_version=control_version+1,state='draft',preview_seal=null,preview_basis=null,
    updated_at=clock_timestamp() where id=d.id returning control_version into next_version;
  result:=jsonb_build_object('schema_version','mission-factory-draft-save/2',
    'request_key',p_request,'draft_id',d.id,'control_version',next_version,'content_kind','quest_ai');
  insert into mission_factory_owner.requests(request_key,actor_user,operation,fingerprint,draft_id,result)
    values(p_request,auth.uid(),'save',fp,d.id,result);
  return result;
end $function$

CREATE OR REPLACE FUNCTION public.npc_combat_approve_v1(p_template uuid, p_narrative_version uuid, p_expected_control_version bigint, p_request_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid:=auth.uid(); v_admin boolean; t public.nb_templates%rowtype;
  nv public.nb_template_versions%rowtype; h png_builder_internal.npc_combat_draft_heads%rowtype;
  mt public.nb_mechanical_templates%rowtype; mv public.nb_mechanical_versions%rowtype;
  fp text; old png_builder_internal.npc_combat_requests%rowtype;
  receipt jsonb; response jsonb; body jsonb;
  approved_mv public.nb_mechanical_versions%rowtype; next_version integer;
begin
  if v_uid is null or not public.is_staff() then raise exception 'NPC_MECH_AUTH' using errcode='42501'; end if;
  select p.role='admin' into v_admin from public.profiles p where p.id=v_uid;
  if not coalesce(v_admin,false) then raise exception 'NPC_MECH_ADMIN_REQUIRED' using errcode='42501'; end if;
  if p_template is null or p_narrative_version is null or p_request_key is null or
     p_expected_control_version is null or p_expected_control_version<1
    then raise exception 'NPC_MECH_ARGUMENT' using errcode='22023'; end if;
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(p_request_key::text,0));
  select * into t from public.nb_templates where id=p_template for update;
  if not found or t.deactivated_at is not null
    then raise exception 'NPC_MECH_UNAVAILABLE' using errcode='42501'; end if;
  fp:=pg_catalog.encode(extensions.digest(pg_catalog.convert_to(
    pg_catalog.jsonb_build_object('operation','approve','template_id',p_template,
      'narrative_version_id',p_narrative_version,
      'expected',p_expected_control_version)::text,'UTF8'),'sha256'),'hex');
  select * into old from png_builder_internal.npc_combat_requests where request_key=p_request_key;
  if found then
    if old.operation<>'approve' or old.actor_id is distinct from v_uid or
       old.narrative_template_id is distinct from p_template or
       old.narrative_version_id is distinct from p_narrative_version or old.fingerprint<>fp
      then raise exception 'NPC_MECH_REQUEST_MISMATCH' using errcode='22023'; end if;
    return pg_catalog.jsonb_set(old.response,'{receipt,replayed}','true'::jsonb,false);
  end if;
  select * into nv from public.nb_template_versions
    where id=p_narrative_version and template_id=p_template for update;
  select * into h from png_builder_internal.npc_combat_draft_heads
    where narrative_template_id=p_template and narrative_version_id=p_narrative_version for update;
  if nv.id is null or nv.review_state<>'review' or h.narrative_template_id is null or
     h.review_state<>'review' or h.control_version<>p_expected_control_version
    then raise exception 'NPC_MECH_STALE' using errcode='55000'; end if;
  if nv.mechanical_template_id is distinct from h.mechanical_template_id or
     h.payload_sha256 is distinct from pg_catalog.encode(extensions.digest(
       pg_catalog.convert_to(h.payload::text,'UTF8'),'sha256'),'hex')
    then raise exception 'NPC_MECH_BINDING_STALE' using errcode='55000'; end if;
  -- The live media register and approve ports require a current approved
  -- narrative version. Media is bound and approved only after this atomic
  -- narrative/mechanical transition, then required by Builder validation.
  -- No unapproved or client-provided media becomes authoritative here.
  if h.combat then
    select * into mt from public.nb_mechanical_templates
      where id=h.mechanical_template_id for update;
    select * into mv from public.nb_mechanical_versions
      where id=h.mechanical_version_id and template_id=h.mechanical_template_id for update;
    body:=pg_catalog.jsonb_build_object(
      'schema_version',mv.schema_version,'rank',mv.rank,'archetype',mv.archetype,
      'base_per_stat',mv.base_per_stat,'allocated_points',mv.allocated_points,
      'innata',mv.innata,'stats',mv.stats,'vita_max',mv.vita_max,
      'chakra_max',mv.chakra_max,'abilities',mv.abilities,'generation',mv.generation);
    if mt.id is null or mt.archetype<>'npc_custom' or mt.lifecycle_state<>'review' or
       mt.active or mt.current_version_id is distinct from mv.id or
       mv.id is null or mv.review_state<>'review' or mv.profile_kind<>'npc_custom' or
       mv.rank<>'NPC' or mv.archetype<>'npc_custom' or mv.abilities<>'[]'::jsonb or
       mv.content_sha256 is distinct from pg_catalog.encode(extensions.digest(
         pg_catalog.convert_to(body::text,'UTF8'),'sha256'),'hex') or
       mv.generation->'clan_ref' is distinct from h.payload->'clan_ref' or
       mv.generation->'chakra_element_ref' is distinct from h.payload->'chakra_element_ref' or
       mv.stats is distinct from h.payload->'stats' or
       mv.vita_max is distinct from (h.payload->>'vita_max')::integer or
       mv.chakra_max is distinct from (h.payload->>'chakra_max')::integer or
       h.payload->'technique_refs'<>'[]'::jsonb or
       h.payload->'ability_refs'<>'[]'::jsonb or
       (h.payload->>'clan_ref' is not null and not exists (
         select 1 from public.clans c where c.name=h.payload->>'clan_ref' and c.is_active))
      then raise exception 'NPC_MECH_VERSION_STALE' using errcode='55000'; end if;
  else
    if h.mechanical_template_id is not null or h.mechanical_version_id is not null or
       h.payload<>'{"combat":false}'::jsonb
      then raise exception 'NPC_MECH_NARRATIVE_SHAPE' using errcode='55000'; end if;
  end if;
  -- NBE Admin authority, skeleton and version transition are rechecked here.
  -- A later failure rolls back this NBE approval in the same transaction.
  perform public.nb_admin_template_approve(p_template,t.control_version,gen_random_uuid());
  if h.combat then
    -- Versions are immutable: approval appends validated content and preserves review history.
    select coalesce(max(v.version_no),0)+1 into next_version
      from public.nb_mechanical_versions v where v.template_id=mt.id;
    insert into public.nb_mechanical_versions(
      template_id,version_no,supersedes_version_id,schema_version,profile_kind,
      rank,archetype,base_per_stat,allocated_points,innata,stats,vita_max,
      chakra_max,abilities,generation,content_sha256,review_state)
    values(mt.id,next_version,mv.id,mv.schema_version,mv.profile_kind,
      mv.rank,mv.archetype,mv.base_per_stat,mv.allocated_points,mv.innata,
      mv.stats,mv.vita_max,mv.chakra_max,mv.abilities,mv.generation,
      mv.content_sha256,'approved') returning * into approved_mv;
    if approved_mv.id is null or approved_mv.id=mv.id or
       approved_mv.supersedes_version_id is distinct from mv.id or
       approved_mv.content_sha256 is distinct from mv.content_sha256 or
       approved_mv.content_sha256 is distinct from pg_catalog.encode(extensions.digest(
         pg_catalog.convert_to(body::text,'UTF8'),'sha256'),'hex') then
      raise exception 'NPC_MECH_APPROVAL_APPEND_DRIFT' using errcode='55000';
    end if;
    update public.nb_mechanical_templates set lifecycle_state='approved',active=true,
      current_version_id=approved_mv.id,control_version=control_version+1,updated_at=clock_timestamp() where id=mt.id;
    insert into public.nb_mechanical_bindings(
      narrative_template_id,narrative_version_id,mechanical_template_id,
      mechanical_version_id,lifecycle_state,active)
    values(p_template,p_narrative_version,mt.id,approved_mv.id,'approved',true);
  end if;
  update png_builder_internal.npc_combat_draft_heads set
    review_state='approved',control_version=control_version+1,
    mechanical_version_id=case when h.combat then approved_mv.id else mechanical_version_id end,
    updated_by=v_uid,updated_at=clock_timestamp()
    where narrative_template_id=p_template and narrative_version_id=p_narrative_version
    returning * into h;
  receipt:=pg_catalog.jsonb_build_object('request_key',p_request_key,'replayed',false,
    'template_id',p_template,'narrative_version_id',p_narrative_version,
    'mechanical_template_id',h.mechanical_template_id,
    'control_version',h.control_version,'payload_sha256',h.payload_sha256);
  update png_builder_internal.npc_combat_draft_heads set last_receipt=receipt
    where narrative_template_id=p_template and narrative_version_id=p_narrative_version;
  response:=png_builder_internal.npc_combat_state_v1(p_template,p_narrative_version);
  insert into png_builder_internal.npc_combat_requests(
    request_key,operation,narrative_template_id,narrative_version_id,actor_id,fingerprint,response)
  values(p_request_key,'approve',p_template,p_narrative_version,v_uid,fp,response);
  return response;
end $function$

CREATE OR REPLACE FUNCTION public.npc_combat_save_v1(p_template uuid, p_narrative_version uuid, p_expected_control_version bigint, p_request_key uuid, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid:=auth.uid(); v_admin boolean; t public.nb_templates%rowtype;
  nv public.nb_template_versions%rowtype; h png_builder_internal.npc_combat_draft_heads%rowtype;
  prev uuid; mech uuid; cat jsonb; sha text; fp text; receipt jsonb; response jsonb;
  old png_builder_internal.npc_combat_requests%rowtype;
  v_combat boolean; v_num numeric; v_field text; v_latest_draft uuid;
begin
  if v_uid is null or not public.is_staff() then raise exception 'NPC_MECH_AUTH' using errcode='42501'; end if;
  if p_template is null or p_narrative_version is null or p_request_key is null
     or p_expected_control_version is null or p_expected_control_version<0
    then raise exception 'NPC_MECH_ARGUMENT' using errcode='22023'; end if;
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(p_request_key::text,0));
  select p.role='admin' into v_admin from public.profiles p where p.id=v_uid;
  select * into t from public.nb_templates where id=p_template for update;
  if not found or t.deactivated_at is not null or
     (t.created_by is distinct from v_uid and not coalesce(v_admin,false))
    then raise exception 'NPC_MECH_UNAVAILABLE' using errcode='42501'; end if;
  select * into nv from public.nb_template_versions
    where id=p_narrative_version and template_id=p_template for update;
  if not found then raise exception 'NPC_MECH_NARRATIVE_MISSING' using errcode='55000'; end if;
  if pg_catalog.jsonb_typeof(p_payload) is distinct from 'object' or
     pg_catalog.jsonb_typeof(p_payload->'combat') is distinct from 'boolean'
    then raise exception 'NPC_MECH_PAYLOAD_SHAPE' using errcode='22023'; end if;
  sha:=pg_catalog.encode(extensions.digest(pg_catalog.convert_to(p_payload::text,'UTF8'),'sha256'),'hex');
  fp:=pg_catalog.encode(extensions.digest(pg_catalog.convert_to(
    pg_catalog.jsonb_build_object('operation','save','template_id',p_template,
      'narrative_version_id',p_narrative_version,'expected',p_expected_control_version,
      'payload_sha256',sha)::text,'UTF8'),'sha256'),'hex');
  select * into old from png_builder_internal.npc_combat_requests where request_key=p_request_key;
  if found then
    if old.operation<>'save' or old.actor_id is distinct from v_uid or
       old.narrative_template_id is distinct from p_template or
       old.narrative_version_id is distinct from p_narrative_version or old.fingerprint<>fp
      then raise exception 'NPC_MECH_REQUEST_MISMATCH' using errcode='22023'; end if;
    return pg_catalog.jsonb_set(old.response,'{receipt,replayed}','true'::jsonb,false);
  end if;
  v_combat:=(p_payload->>'combat')::boolean;
  if not v_combat then
    if p_payload<>'{"combat":false}'::jsonb
      then raise exception 'NPC_MECH_PAYLOAD_SHAPE' using errcode='22023'; end if;
  else
    if not (p_payload ?& array['combat','stats','vita_max','chakra_max',
      'technique_refs','ability_refs','clan_ref','chakra_element_ref','catalog_digest'])
      or p_payload-array['combat','stats','vita_max','chakra_max','technique_refs',
        'ability_refs','clan_ref','chakra_element_ref','catalog_digest']<>'{}'::jsonb
      or not png_builder_internal.npc_combat_stats_safe(p_payload->'stats')
      or p_payload->'technique_refs'<>'[]'::jsonb
      or p_payload->'ability_refs'<>'[]'::jsonb
      then raise exception 'NPC_MECH_PAYLOAD_SHAPE' using errcode='22023'; end if;
    foreach v_field in array array['vita_max','chakra_max'] loop
      if pg_catalog.jsonb_typeof(p_payload->v_field) is distinct from 'number'
        then raise exception 'NPC_MECH_RESOURCE_SHAPE' using errcode='22023'; end if;
      v_num:=(p_payload->>v_field)::numeric;
      if v_num<>pg_catalog.trunc(v_num) or v_num>2147483647 or
         (v_field='vita_max' and v_num<1) or (v_field='chakra_max' and v_num<0)
        then raise exception 'NPC_MECH_RESOURCE_RANGE' using errcode='22023'; end if;
    end loop;
    cat:=public.npc_combat_catalog_v1(p_template);
    if p_payload->>'catalog_digest' is distinct from cat->>'catalog_digest'
      then raise exception 'NPC_MECH_CATALOG_STALE' using errcode='55000'; end if;
    if p_payload->>'clan_ref' is not null and not exists (
      select 1 from public.clans c where c.name=p_payload->>'clan_ref' and c.is_active)
      then raise exception 'NPC_MECH_REF_ILLEGAL' using errcode='22023'; end if;
    if p_payload->>'chakra_element_ref' is not null and
       p_payload->>'chakra_element_ref' <> all(array['Acqua','Fulmine','Fuoco','Terra','Vento'])
      then raise exception 'NPC_MECH_REF_ILLEGAL' using errcode='22023'; end if;
    if pg_catalog.jsonb_typeof(p_payload->'clan_ref') not in ('string','null') or
       pg_catalog.jsonb_typeof(p_payload->'chakra_element_ref') not in ('string','null')
      then raise exception 'NPC_MECH_REF_ILLEGAL' using errcode='22023'; end if;
  end if;
  if nv.review_state<>'draft' then
    raise exception 'NPC_MECH_NARRATIVE_NOT_DRAFT' using errcode='55000';
  end if;
  select v.id into v_latest_draft from public.nb_template_versions v
    where v.template_id=p_template and v.review_state='draft'
    order by v.version_no desc limit 1;
  if v_latest_draft is distinct from p_narrative_version then
    raise exception 'NPC_MECH_NARRATIVE_STALE' using errcode='55000';
  end if;
  select * into h from png_builder_internal.npc_combat_draft_heads
    where narrative_template_id=p_template and narrative_version_id=p_narrative_version for update;
  if found then
    if h.control_version<>p_expected_control_version or h.review_state<>'draft'
      then raise exception 'NPC_MECH_STALE' using errcode='55000'; end if;
  elsif p_expected_control_version<>0 then
    raise exception 'NPC_MECH_STALE' using errcode='55000';
  end if;
  mech:=case when v_combat then h.mechanical_template_id else null end;
  if v_combat and mech is null then
    select r.mechanical_template_id into mech
      from png_builder_internal.npc_combat_draft_revisions r
      where r.narrative_template_id=p_template and r.narrative_version_id=p_narrative_version
        and r.mechanical_template_id is not null
      order by r.control_version desc limit 1;
    if mech is null then
      insert into public.nb_mechanical_templates(template_key,archetype,lifecycle_state,active)
      values ('nbm_npc_'||pg_catalog.replace(p_narrative_version::text,'-',''),
        'npc_custom','draft',false) returning id into mech;
    end if;
  end if;
  select r.id into prev from png_builder_internal.npc_combat_draft_revisions r
    where r.narrative_template_id=p_template and r.narrative_version_id=p_narrative_version
    order by r.control_version desc limit 1;
  if h.narrative_template_id is null then
    insert into png_builder_internal.npc_combat_draft_heads(
      narrative_template_id,narrative_version_id,mechanical_template_id,combat,payload,
      payload_sha256,control_version,created_by,updated_by)
    values(p_template,p_narrative_version,mech,v_combat,p_payload,sha,1,v_uid,v_uid)
    returning * into h;
  else
    update png_builder_internal.npc_combat_draft_heads set
      mechanical_template_id=mech,mechanical_version_id=null,combat=v_combat,
      payload=p_payload,payload_sha256=sha,control_version=control_version+1,
      updated_by=v_uid,updated_at=clock_timestamp()
      where narrative_template_id=p_template and narrative_version_id=p_narrative_version
      returning * into h;
  end if;
  insert into png_builder_internal.npc_combat_draft_revisions(
    narrative_template_id,narrative_version_id,control_version,previous_revision_id,
    mechanical_template_id,combat,payload,payload_sha256,actor_id,request_key)
  values(p_template,p_narrative_version,h.control_version,prev,mech,v_combat,
    p_payload,sha,v_uid,p_request_key);
  receipt:=pg_catalog.jsonb_build_object('request_key',p_request_key,'replayed',false,
    'template_id',p_template,'narrative_version_id',p_narrative_version,
    'mechanical_template_id',mech,'control_version',h.control_version,'payload_sha256',sha);
  update png_builder_internal.npc_combat_draft_heads set last_receipt=receipt
    where narrative_template_id=p_template and narrative_version_id=p_narrative_version;
  response:=png_builder_internal.npc_combat_state_v1(p_template,p_narrative_version);
  insert into png_builder_internal.npc_combat_requests(
    request_key,operation,narrative_template_id,narrative_version_id,actor_id,fingerprint,response)
  values(p_request_key,'save',p_template,p_narrative_version,v_uid,fp,response);
  return response;
exception when numeric_value_out_of_range or invalid_text_representation then
  raise exception 'NPC_MECH_RESOURCE_SHAPE' using errcode='22023';
end $function$

CREATE OR REPLACE FUNCTION public.npc_combat_submit_review_v1(p_template uuid, p_narrative_version uuid, p_expected_control_version bigint, p_request_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid:=auth.uid(); v_admin boolean; t public.nb_templates%rowtype;
  nv public.nb_template_versions%rowtype; h png_builder_internal.npc_combat_draft_heads%rowtype;
  mt public.nb_mechanical_templates%rowtype; mv uuid; latest uuid; body jsonb;
  fp text; old png_builder_internal.npc_combat_requests%rowtype;
  receipt jsonb; response jsonb;
begin
  if v_uid is null or not public.is_staff() then raise exception 'NPC_MECH_AUTH' using errcode='42501'; end if;
  if p_template is null or p_narrative_version is null or p_request_key is null or
     p_expected_control_version is null or p_expected_control_version<1
    then raise exception 'NPC_MECH_ARGUMENT' using errcode='22023'; end if;
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(p_request_key::text,0));
  select p.role='admin' into v_admin from public.profiles p where p.id=v_uid;
  select * into t from public.nb_templates where id=p_template for update;
  if not found or t.deactivated_at is not null or
     (t.created_by is distinct from v_uid and not coalesce(v_admin,false))
    then raise exception 'NPC_MECH_UNAVAILABLE' using errcode='42501'; end if;
  fp:=pg_catalog.encode(extensions.digest(pg_catalog.convert_to(
    pg_catalog.jsonb_build_object('operation','submit_review','template_id',p_template,
      'narrative_version_id',p_narrative_version,
      'expected',p_expected_control_version)::text,'UTF8'),'sha256'),'hex');
  select * into old from png_builder_internal.npc_combat_requests where request_key=p_request_key;
  if found then
    if old.operation<>'submit_review' or old.actor_id is distinct from v_uid or
       old.narrative_template_id is distinct from p_template or
       old.narrative_version_id is distinct from p_narrative_version or old.fingerprint<>fp
      then raise exception 'NPC_MECH_REQUEST_MISMATCH' using errcode='22023'; end if;
    return pg_catalog.jsonb_set(old.response,'{receipt,replayed}','true'::jsonb,false);
  end if;
  select * into nv from public.nb_template_versions
    where id=p_narrative_version and template_id=p_template for update;
  select * into h from png_builder_internal.npc_combat_draft_heads
    where narrative_template_id=p_template and narrative_version_id=p_narrative_version for update;
  if nv.id is null or nv.review_state<>'draft' or h.narrative_template_id is null or
     h.review_state<>'draft' or h.control_version<>p_expected_control_version
    then raise exception 'NPC_MECH_STALE' using errcode='55000'; end if;
  select v.id into latest from public.nb_template_versions v
    where v.template_id=p_template and v.review_state='draft'
    order by v.version_no desc limit 1;
  if latest is distinct from p_narrative_version then
    raise exception 'NPC_MECH_NARRATIVE_STALE' using errcode='55000'; end if;
  if h.payload_sha256 is distinct from pg_catalog.encode(extensions.digest(
       pg_catalog.convert_to(h.payload::text,'UTF8'),'sha256'),'hex')
    then raise exception 'NPC_MECH_PAYLOAD_DRIFT' using errcode='55000'; end if;
  if nv.mechanical_template_id is distinct from h.mechanical_template_id
    then raise exception 'NPC_MECH_NBE_POINTER_MISMATCH' using errcode='55000'; end if;
  if h.combat then
    if not png_builder_internal.npc_combat_stats_safe(h.payload->'stats') or
       h.payload->'technique_refs'<>'[]'::jsonb or
       h.payload->'ability_refs'<>'[]'::jsonb
      then raise exception 'NPC_MECH_REF_ILLEGAL' using errcode='22023'; end if;
    select * into mt from public.nb_mechanical_templates
      where id=h.mechanical_template_id for update;
    if mt.id is null or mt.archetype<>'npc_custom' or mt.lifecycle_state<>'draft' or
       mt.active or mt.current_version_id is not null
      then raise exception 'NPC_MECH_TEMPLATE_STALE' using errcode='55000'; end if;
    body:=pg_catalog.jsonb_build_object(
      'schema_version','ninja-book-mechanics/npc-custom/1.0',
      'rank','NPC','archetype','npc_custom','base_per_stat',0,
      'allocated_points',0,'innata',0,'stats',h.payload->'stats',
      'vita_max',(h.payload->>'vita_max')::integer,
      'chakra_max',(h.payload->>'chakra_max')::integer,
      'abilities','[]'::jsonb,
      'generation',pg_catalog.jsonb_build_object('source','staff',
        'clan_ref',h.payload->'clan_ref',
        'chakra_element_ref',h.payload->'chakra_element_ref'));
    insert into public.nb_mechanical_versions(
      template_id,version_no,schema_version,rank,archetype,base_per_stat,
      allocated_points,innata,stats,vita_max,chakra_max,abilities,generation,
      content_sha256,review_state,profile_kind)
    values(mt.id,1,'ninja-book-mechanics/npc-custom/1.0','NPC','npc_custom',0,
      0,0,h.payload->'stats',(h.payload->>'vita_max')::integer,
      (h.payload->>'chakra_max')::integer,'[]'::jsonb,body->'generation',
      pg_catalog.encode(extensions.digest(pg_catalog.convert_to(body::text,'UTF8'),'sha256'),'hex'),
      'review','npc_custom') returning id into mv;
    update public.nb_mechanical_templates set lifecycle_state='review',
      current_version_id=mv,control_version=control_version+1,updated_at=clock_timestamp()
      where id=mt.id;
  end if;
  -- Native NBE checks actor Staff, skeleton and transition. Any failure rolls
  -- back the mechanical version and all gateway writes in this same call.
  perform public.nb_admin_template_submit_review(p_template,t.control_version,gen_random_uuid());
  update png_builder_internal.npc_combat_draft_heads set
    mechanical_version_id=mv,review_state='review',control_version=control_version+1,
    updated_by=v_uid,updated_at=clock_timestamp()
    where narrative_template_id=p_template and narrative_version_id=p_narrative_version
    returning * into h;
  receipt:=pg_catalog.jsonb_build_object('request_key',p_request_key,'replayed',false,
    'template_id',p_template,'narrative_version_id',p_narrative_version,
    'mechanical_template_id',h.mechanical_template_id,
    'control_version',h.control_version,'payload_sha256',h.payload_sha256);
  update png_builder_internal.npc_combat_draft_heads set last_receipt=receipt
    where narrative_template_id=p_template and narrative_version_id=p_narrative_version;
  response:=png_builder_internal.npc_combat_state_v1(p_template,p_narrative_version);
  insert into png_builder_internal.npc_combat_requests(
    request_key,operation,narrative_template_id,narrative_version_id,actor_id,fingerprint,response)
  values(p_request_key,'submit_review',p_template,p_narrative_version,v_uid,fp,response);
  return response;
end $function$
